/* chronicle data chunk: cn-06 | 近代中国 1840–1949 | 生成于 2026-09-21 */
window.__CHRONICLE_CHUNK = window.__CHRONICLE_CHUNK || {};
window.__CHRONICLE_CHUNK["cn-06"] = [
  { id: "cn--1840--p01", track: "cn", year: 1840, yearApprox: false, dim: "politics", weight: 5, title: "鸦片战争正式爆发", summary: "英舰队封粤海，北驶犯浙津。", detail: { background: "中英贸易断绝后，英国于1840年2月决定派兵，任懿律、义律为正副全权代表，编东方远征军。", process: "1840年6月英舰船四十余艘、陆军约四千人抵广东海面，因粤防整固转以北驶，7月陷定海，8月至天津大沽口外投递照会；直隶总督琦善劝以返粤可办，宣宗意摇，命琦善为钦差赴粤查办，谕沿海撤防。", impact: "战争由地方查禁鸦片一变而为两国之战，清廷在剿抚之间反复，海防与奏报系统的失灵同时暴露。此后中国割地、赔款、开五口、定税则，近代条约体制与海防危机皆以此役为起点。", figures: ["懿律","义律","旻宁","琦善","林则徐"], place: "广东珠江口至天津大沽口", state: "清", sources: ["《（道光）筹办夷务始末》道光朝卷二一","马士《中华帝国对外关系史》卷一","魏源《道光洋艘征抚记》"], tags: ["鸦片战争","开衅"] }, related: ["cn--1839--p02", "cn--1842--p01", "world--1839--p01"] },
  { id: "cn--1840--m01", track: "cn", year: 1840, yearApprox: false, dim: "military", weight: 3, title: "英军北犯陷定海", summary: "浙东门户先失，总兵被创。", detail: { background: "浙江水师以镇海、定海为宁波门户，炮台废弛而兵丁不练。", process: "1840年7月5日英舰北犯定海，总兵张朝发率师船迎战被创，知县姚燮守城不守，城陷，为鸦片战争中第一个被攻占的州县城；英军留兵驻定海、封锁宁波口，8月继续北驶。", impact: "定海失守震动朝野，成为宣宗由主剿转为主抚的直接缘由之一；英军以定海为补给与侦察基地，1841年秋再取镇海、宁波之役由此出发，东南财赋之地暴露于舰炮之下。", figures: ["张朝发","姚燮","懿律"], place: "浙江定海（今舟山）", state: "清", sources: ["《清史稿·张朝发传》","（道光）《浙江海防录》","马士《中华帝国对外关系史》卷一"], tags: ["定海","海防"] }, related: ["cn--1840--p01", "cn--1841--m04"] },
  { id: "cn--1840--c01", track: "cn", year: 1840, yearApprox: false, dim: "culture", weight: 3, title: "《四洲志》译编成", summary: "译西人地志，开论世界之先。", detail: { background: "林则徐到粤后以须悉夷情为辞，募通事与学生译外国报刊、书籍。", process: "1839至1840年间，慕瑞所撰世界地理书由译员节译，林则徐亲加删订成《四洲志》，述亚、欧、美、非诸国之地理、政体与沿革，并录华盛顿事迹与议会、民举之制。", impact: "此书为近代第一部由官员主持编译的世界地理志，魏源据之以成《海国图志》；其中论美国立国与选举之数段，成为晚清议政体者最常征引之文，开眼看世界之局自粤中译书始。", figures: ["林则徐","魏源"], place: "广东广州（今广州）", state: "清", sources: ["林则徐《四洲志》","魏源《海国图志》原叙","杨国桢《林则徐传》"], tags: ["四洲志","世界知识"] }, related: ["cn--1842--c01"] },
  { id: "cn--1841--p01", track: "cn", year: 1841, yearApprox: false, dim: "politics", weight: 4, title: "穿鼻草约与琦善获罪", summary: "约未奏而岛已让。", detail: { background: "琦善代林则徐至粤，主以复商退兵，撤沙角、大角守备，与义律往来商议。", process: "1841年1月英军登岸据香港岛，2月琦善与义律议定草约，许英人寄寓香港、赔偿烟价并复粤海贸易；琦善未奉准画押，事闻，宣宗以擅主之罪革职锁拿、籍家，改派奕山为靖逆将军，草约为双方同时否认。", impact: "此案暴露清朝外交决策与前线办事的彻底脱节：既不能战，又不能守约，英方要求由赔烟价升为割地、赔兵费、开口与立章程，战争目标逐步扩大，而清廷已无谈判筹码。", figures: ["琦善","义律","旻宁"], place: "广东广州、香港（今广州、香港）", state: "清", sources: ["《（道光）筹办夷务始末》道光朝卷二五","马士《中华帝国对外关系史》卷一","佐佐木正哉《鸦片战争的研究》"], tags: ["穿鼻草约","割地"] }, related: ["cn--1841--m01", "cn--1842--p01"] },
  { id: "cn--1841--m01", track: "cn", year: 1841, yearApprox: false, dim: "military", weight: 4, title: "英军强占香港岛", summary: "一岛悬英旗，粤海形势遂变。", detail: { background: "义律以草约未定而英政府训令须取据地，借口断供与村民被殴案继续施压。", process: "1841年1月26日英军水兵登陆香港岛升旗，29日义律与粤地方官会勘，声称占据全岛及其海面港口，居民田产归其保护；岛上有居民数千（英方调查约二千至七千余，诸说互异），清方未作一兵之拒。", impact: "香港自此入英国统治，成为转口贸易、苦力出口与对华情报活动之枢；清廷在《南京条约》中以让与字样承认既成事实，沿海边界与地面管辖之权自此在条约口岸不断流失。", figures: ["义律","琦善"], place: "香港岛（今香港）", state: "清", sources: ["义律致巴麦尊公文，载英国《议会文书·中国事务》","马士《中华帝国对外关系史》卷一","《（道光）筹办夷务始末》卷二五"], tags: ["香港","割占"] }, related: ["cn--1841--p01", "cn--1842--p01"] },
  { id: "cn--1841--m02", track: "cn", year: 1841, yearApprox: false, dim: "military", weight: 4, title: "虎门之战与关天培死事", summary: "台无后防，炮不能仰俯。", detail: { background: "关天培自1835年任广东水师提督，在虎门东西岸增筑威远、镇远、横档诸台，铸铁链截江。", process: "1841年2月23日至26日英舰以重炮压制岸台，分兵登岸绕取横档后路，两路夹击威远、镇远；关天培守镇远台，药尽力战而死，所部死者数百人，虎门诸台数日俱陷。", impact: "广州门户洞开，奕山、杨芳入粤后只能守城议款；此役以实证显出固定炮台对机动蒸汽舰队的劣势：台无后防、炮位旧式、兵未操练，其教训在后日江南制造局与练兵之议中仍被反复征引。", figures: ["关天培","义律"], place: "广东虎门（今东莞虎门）", state: "清", sources: ["《清史稿·关天培传》","《（道光）筹办夷务始末》卷二七","魏源《道光洋艘征抚记》"], tags: ["虎门","战殁"] }, related: ["cn--1839--m01", "cn--1841--p02"] },
  { id: "cn--1841--p02", track: "cn", year: 1841, yearApprox: false, dim: "politics", weight: 4, title: "奕山广州城下之盟", summary: "兵败议款，许缴六百万元。", detail: { background: "1841年正月命奕山为靖逆将军，调川湘绿营进粤，兵未集而英军已薄城。", process: "4月英军占广州西北炮台，环城俯击，城中文武溃乱；5月27日奕山、杨芳与义律订立广州善后条款，许七日缴兵费六百万元、清军退城六十里，英军不复入城，而奏疏以羁縻从事。", impact: "此盟使抚局一路主导清廷对英之策；广东民间由是既恶外夷亦轻官府，三元里之役即在官军退驻、乡里自守之局中发生。以败为胜、以赔为赏的奏报方式，使庙算与实情愈益两途。", figures: ["奕山","杨芳","义律"], place: "广东广州（今广州）", state: "清", sources: ["《（道光）筹办夷务始末》卷三一","《清史稿·奕山传》","义律公文载英国《议会文书》"], tags: ["广州和议","城下之盟"] }, related: ["cn--1841--m02", "cn--1841--m03"] },
  { id: "cn--1841--m03", track: "cn", year: 1841, yearApprox: false, dim: "military", weight: 3, title: "三元里抗英", summary: "乡团围英于牛栏冈，粤民自战。", detail: { background: "英军出城征粮、发掘冢墓，广州北郊诸乡团练积愤，何玉瞽等以庙集众相约。", process: "1841年5月29日至31日，三元里、萧村等百余乡团众围英军于牛栏冈、四角塘一带，值大雨英军火器失效；清方与英方所记英军死伤自数十人至二百余人不等，广州知府余保纯出面劝退，团众始散。", impact: "此为近代民众自发对外的第一次武装冲突，粤省民强于官之形势自此显于中外记载；然官府既不能恃民，亦不敢用民，其后广东反入城与排外风潮延续十年，反成条约体制下的难题。", figures: ["何玉瞽","余保纯","义律"], place: "广州北郊三元里（今广州白云）", state: "清", sources: ["《（道光）筹办夷务始末》卷三二","梁廷枏《夷氛闻记》","英军战报载英国《议会文书》"], tags: ["三元里","民团"] }, related: ["cn--1841--p02", "cn--1845--p01"] },
  { id: "cn--1841--m04", track: "cn", year: 1841, yearApprox: false, dim: "military", weight: 3, title: "定海镇海之陷，三总兵死事", summary: "两昼夜力战，三镇俱歿。", detail: { background: "英军以定海为基地，1841年秋增兵来犯，浙防以定海、镇海、宁波为犄角。", process: "1841年9月26日至10月1日英舰再犯定海，总兵葛云飞、王化鹏、郑国鸿率兵三千余守土门、竹山门诸要，苦战两昼夜俱战歿，城陷；10月10日镇海继陷，钦差大臣裕谦赴水死，宁波同日失守。", impact: "浙东三镇之失使清廷不得不承认绿营、旗兵不能敌舰炮，伊里布、耆英以抚再主其议；同时地方绅民办团练、筹粮自守之例由此起，为咸丰以后督抚专兵、地方自保之局张本。", figures: ["葛云飞","裕谦","砵甸乍"], place: "浙江定海、镇海、宁波", state: "清", sources: ["《清史稿·葛云飞传》《裕谦传》","（道光）《浙江海防录》","马士《中华帝国对外关系史》卷一"], tags: ["浙东","战歿"] }, related: ["cn--1840--m01", "cn--1842--m01"] },
  { id: "cn--1841--d01", track: "cn", year: 1841, yearApprox: false, dim: "disaster", weight: 3, title: "黄河祥符大决", summary: "口门数百丈，夺淮南注经年。", detail: { background: "黄河自嘉庆间屡决，河南祥符、中牟段堤防失修，是年伏雨连旬、河水盛涨。", process: "1841年8月2日黄河决河南祥符（今开封）十二堡，口门宽二百余丈至四百余丈，水南注由贾鲁河入洪泽湖、夺淮入海，凤、颍、泗、淮所属州县同时被淹，开封城内外积水经年，堵筑历八月始合龙。", impact: "河、漕、盐三政同时受困：淮南盐船改道、漕粮受阻，海运与票法之议再起；工赈费银千数百万两，沿淮饥民流徙，捻党起事不绝。近代学者推定此次河患之死亡与流徙人数以数十万计，诸志所载互异。", figures: ["栗毓美","旻宁"], place: "河南祥符（今开封）", state: "清", sources: ["《清史稿·河渠志》","《（道光）上谕档》与河督奏销册","邹逸麟《黄淮海平原历史地理》"], tags: ["河决","灾荒"] }, related: ["cn--1853--i01"] },
  { id: "cn--1841--f01", track: "cn", year: 1841, yearApprox: false, dim: "figure", weight: 1, title: "龚自珍卒", summary: "剑气箫心，为晚清先声。", detail: { background: "龚自珍（1792—1841）字璱人，号定盦，浙江仁和人，道光九年进士，官礼部主事，以言事不售辞归。", process: "1841年八月龚自珍卒于江苏丹阳云阳书院，年五十；著有《定盦文集》，别辑《六经正名》《五经大义终始论》，其《己亥杂诗》劝天公重抖擞、不拘一格降人才一绝最传。", impact: "其以今文经学论三世、讥科举与吏治，为晚清维新派公认之先声，康有为、梁启超、谭嗣同皆自谓受其影响；论漕河、盐、边政诸篇承《皇朝经世文编》之风，而文辞之奇崛为一代之冠。", figures: ["龚自珍"], place: "江苏丹阳（今丹阳）", state: "清", sources: ["龚自珍《定盦文集》","《清史稿·文苑传》","钱基博《现代中国文学史》"], tags: ["龚自珍","今文经学"] }, related: ["cn--1826--c01"] },
  { id: "cn--1842--m01", track: "cn", year: 1842, yearApprox: false, dim: "military", weight: 4, title: "英军陷镇江，兵临江宁", summary: "一昼夜而京口陷，漕路遂断。", detail: { background: "英以扼长江、断漕运为决胜之策，1842年5月再陷乍浦后悉众入江。", process: "1842年7月21日英军攻京口（镇江），副都统海龄率旗兵巷战，城一昼夜而陷，海龄死之，英军亦遭开战以来最重之死伤（英方记军官、兵丁伤亡三百余人）；8月初英舰上驶，泊江宁城下江面，两江震动。", impact: "长江与运河既被截断，东南漕粮、盐课皆停，清廷丧失继续作战的财政与意志，乃命耆英、伊里布赶到议和；此役实为鸦片战争的决战，其后条约之成即在兵临城下之日。", figures: ["海龄","璞鼎查","耆英"], place: "江苏镇江、江宁（今镇江、南京）", state: "清", sources: ["《清史稿·海龄传》","《（道光）筹办夷务始末》卷五八","马士《中华帝国对外关系史》卷一"], tags: ["镇江","长江"] }, related: ["cn--1842--p01", "cn--1841--m04", "world--1842--p01"] },
  { id: "cn--1842--p01", track: "cn", year: 1842, yearApprox: false, dim: "politics", weight: 5, title: "中英《南京条约》签订", summary: "近代第一约，割地赔款开五口。", detail: { background: "璞鼎查以割地、赔款、开口、明定税则、释英民为条件，不许另立公文格式；耆英、伊里布奉命便宜行事。", process: "1842年8月29日《江宁条约》十三款在英舰康华丽号签订：割香港岛，赔款二千一百万元分四年交清，开广州、厦门、福州、宁波、上海五口通商，英商进出口税则秉公议定，废广东行商保商之制。", impact: "此约以中外文本并立，破坏了清之关税、司法与贸易垄断体制；其议税一条使中国此后不能自立税则，1843年《虎门条约》与美法诸约又增领事裁判、片面最惠国与传教条款，条约体制由此成网，近代外交、海关与财政被迫重构。", figures: ["耆英","伊里布","璞鼎查"], place: "江苏江宁（今南京）", state: "清", sources: ["王铁崖编《中外旧约章汇编》第一册《江宁条约》","马士《中华帝国对外关系史》卷一","《（道光）筹办夷务始末》卷六〇"], tags: ["南京条约","开埠"] }, related: ["cn--1843--p01", "cn--1842--m01", "world--1842--p01"] },
  { id: "cn--1842--c01", track: "cn", year: 1842, yearApprox: false, dim: "culture", weight: 4, title: "《海国图志》成书", summary: "师夷长技以制夷。", detail: { background: "魏源受林则徐之托，据《四洲志》与粤中所译西书、地图、报刊增订成编。", process: "1842年底《海国图志》五十卷成，其后扩为六十卷、一百卷，述世界地理、各国政事船炮战法与南洋、印度之局，倡「师夷长技以制夷」「以夷制夷」，请设船局、火器局，延夷匠而制其技。", impact: "此书规定此后五十年中国人认识世界的框架；1851年东传日本，幕末志士佐久间象山、吉田松阴皆据以论海防，对日本开国思想影响尤大。「师夷长技」一语则为洋务运动在观念上的源头。", figures: ["魏源","林则徐"], place: "江苏扬州（今扬州）", state: "清", sources: ["魏源《海国图志》原叙、凡例","《魏源集》","佐久间象山《省身录》"], tags: ["海国图志","师夷长技"] }, related: ["cn--1840--c01", "cn--1862--i01"] },
  { id: "cn--1842--f01", track: "cn", year: 1842, yearApprox: false, dim: "figure", weight: 2, title: "林则徐遣戍伊犁", summary: "谪臣勘垦，塞外始修水利。", detail: { background: "1841年以误国启兵端之罪革去卿衔、从重遣戍，途中奉命协办河南祥符、浙江海防诸工。", process: "1842年12月林则徐抵伊犁惠远城，以废员效力，勘察伊南、吐鲁番一带水源，筹浚坎儿井、拓地招垦，关外民户感之称其所浚为林公渠；在戍三年，与伊犁将军布彦泰论边政屯务，主守边实边、防俄。", impact: "新疆东路屯政与水利因之修明，布彦泰据其勘地之议奏请开垦伊犁惠宁城水南之地，为道咸间新疆屯垦之要着；而此疏于时务最切、于外情最深之大员久弃边塞，成为后来论御外之策者常举之例。", figures: ["林则徐","布彦泰"], place: "伊犁惠远城（今新疆霍城）", state: "清", sources: ["林则徐《荷竿集》与《林文忠公政书》","《（道光）新疆屯垦档案》","杨国桢《林则徐传》"], tags: ["伊犁","屯垦"] }, related: ["cn--1840--c01", "cn--1850--f01"] },
  { id: "cn--1843--p01", track: "cn", year: 1843, yearApprox: false, dim: "politics", weight: 4, title: "《虎门条约》与五口通商章程", summary: "协定关税与领事裁判权入约。", detail: { background: "《江宁条约》仅定大纲，税则、地界与诉讼章程须另订专约，璞鼎查留澳门督催。", process: "1843年7月《五口通商章程》在香港宣布，定英人涉讼由英国领事查办、进出口税按值百抽五；10月中英《虎门条约》十六款签订，又定一体均沾之片面最惠国、英船准在五口往来与租地建屋之条。", impact: "协定关税与领事裁判两项，成为此后历次修约谈判中中国欲收回而不可得的枢纽；值百抽五使中国永失保护性税则，租地一条则为各国租界提供了法律依据，而一体均沾使一国所得诸国同享。", figures: ["耆英","璞鼎查"], place: "香港、澳门（今香港、澳门）", state: "清", sources: ["王铁崖编《中外旧约章汇编》第一册","马士《中华帝国对外关系史》卷一","丁名楠等《帝国主义侵华史》第一卷"], tags: ["虎门条约","领事裁判"] }, related: ["cn--1842--p01", "cn--1844--p01"] },
  { id: "cn--1843--e01", track: "cn", year: 1843, yearApprox: false, dim: "economy", weight: 4, title: "五口开埠与上海代兴", summary: "外贸北移，一埠立而商路改。", detail: { background: "五口依约先后开关，广州、厦门、上海在1843年冬至1844年春，宁波、福州继之。", process: "上海以吴淞口、黄浦江与苏松腹地之便，开埠数年即夺广州之利：1843年在沪洋行不过数十家，1845年后茶丝出口岁增，至1850年代上海一埠已占全国茶叶出口半数以上；洋布、洋棉由是溯江入内地，江南土布与乡村纺绩之业始受其挤。", impact: "贸易重心北移使十三行与粤海关体系失其枢纽，粤省商伙、通事、船户失业者众；江南丝茶产区、市镇江关与买办、钱庄、票号连成新网络，上海由此渐成近代工业、金融、航运与出版之中心，中国经济地理为之一变。", figures: ["耆英","巴富尔"], place: "江苏上海（今上海）", state: "清", sources: ["各关《华洋贸易情形论略》册报","马士《中华帝国对外关系史》卷一","《（道光）江苏巡抚奏稿》"], tags: ["开埠","上海"] }, related: ["cn--1845--i01", "cn--1843--p01"] },
  { id: "cn--1843--p02", track: "cn", year: 1843, yearApprox: false, dim: "politics", weight: 3, title: "洪秀全立拜上帝会", summary: "弃塾师之偶像，立上帝之会。", detail: { background: "洪秀全（1814—1864）广东花县人，四次应童子试不第，1843年读梁发《劝世良言》而有悟。", process: "1843年洪秀全在花县与冯云山、洪仁玕同立拜上帝会，独尊上帝、不拜神佛邪精，作《原道救世歌》以劝世；1844年往广西贵县赐谷村传教无所获，冯云山转入桂平紫荆山中佣工设馆，山民入会者渐众。", impact: "此会以宗教、亲族与贫苦山民三重纽带组织烧炭客民，其教义与后来的圣库、天朝田亩制度相贯，1851年遂成金田之起；以西方布道册子为原料而兴的运动，此后十四年席卷南部十八省，为清代人口与财政由盛转衰之枢纽。", figures: ["洪秀全","冯云山","洪仁玕"], place: "广东花县（今广州市花都）", state: "清", sources: ["韩山文《太平天国起义记》","《洪仁玕自述》","罗尔纲《太平天国史》"], tags: ["拜上帝会","洪秀全"] }, related: ["cn--1832--c01", "cn--1844--p04"] },
  { id: "cn--1844--p01", track: "cn", year: 1844, yearApprox: false, dim: "politics", weight: 3, title: "中美《望厦条约》", summary: "美国以一说而获英人战得之利。", detail: { background: "美国以顾盛为专使来华，取道澳门，扬言不得约即北赴天津。", process: "1844年7月顾盛与耆英在澳门望厦村订中美《五口贸易章程》三十四款：除中英已有诸权外，并定中国更改税则须先行知照领事、英人只准在五口贸易，且约以十二年后两国可派员相商更改。", impact: "十二年修约之约成为1854、1856年两次修约要求与第二次鸦片战争的伏线；美国不费一兵而获英国用兵所得，列强以条约链相维之局遂成，清政府亦自此学会在条约格式之内讨价还价。", figures: ["顾盛","耆英"], place: "澳门望厦村（今澳门）", state: "清", sources: ["王铁崖编《中外旧约章汇编》第一册","《（道光）筹办夷务始末》卷六五","丁名楠等《帝国主义侵华史》第一卷"], tags: ["望厦条约","修约"] }, related: ["cn--1843--p01", "cn--1856--m01"] },
  { id: "cn--1844--p02", track: "cn", year: 1844, yearApprox: false, dim: "politics", weight: 3, title: "中法《黄埔条约》", summary: "法得约款，兼索传教之弛禁。", detail: { background: "法国以喇萼尼为专使率舰来粤，借交还天主堂地基一案相要结。", process: "1844年10月中法《五口贸易章程》签于广州黄埔泊船，除开口通商、领事裁判诸条外，许法人在五口建造教堂、医院、坟地；喇萼尼续向耆英索禁教之弛，清廷于年末准将雍正、乾隆间入官之天主堂产发还习教免罪。", impact: "弛禁使传教士依条约入内地置产建堂，教案自此与条约、地方社会三者交纠不绝，至1870年天津教案而大爆发；法国以护教为对华交涉之常备杠杆，此约为其始。", figures: ["喇萼尼","耆英"], place: "广州黄埔（今广州）", state: "清", sources: ["王铁崖编《中外旧约章汇编》第一册","《（道光）筹办夷务始末》卷六六","费赖之《入华耶稣会士列传》"], tags: ["黄埔条约","弛禁"] }, related: ["cn--1844--p03", "cn--1870--p01"] },
  { id: "cn--1844--p03", track: "cn", year: 1844, yearApprox: false, dim: "politics", weight: 3, title: "弛天主教之禁", summary: "百年之禁，因一约而开。", detail: { background: "自1721年礼部议禁以来，天主堂产多被入官，教民潜伏于川陕、江南山地。", process: "1844年末道光帝以五口通商已定，准将各直省雍正乾隆间入官之天主堂屋发还主教、习教者免其查办；谕中犹称不许内地民人从教，而地方官遂以不发堂、不查拿为奉行条约。", impact: "弛禁与条约并行，使教会势力由沿边进入腹地，入教者赖以免役抗租，乡里祠祀、会款之争因而激化；此后教案频仍而清廷须按约保护，处置在两重压力之下，地方官失信于民，成为晚清统治危机之一端。", figures: ["旻宁","耆英"], place: "京师（今北京）", state: "清", sources: ["《（道光）筹办夷务始末》道光朝上谕档","《清实录》宣宗朝","费赖之《入华耶稣会士列传》"], tags: ["弛禁","教案"] }, related: ["cn--1721--c01", "cn--1844--p02"] },
  { id: "cn--1844--i01", track: "cn", year: 1844, yearApprox: false, dim: "institution", weight: 2, title: "设五口通商大臣", summary: "夷务无部，专归两广总督兼理。", detail: { background: "条约既成而理藩院、礼部皆无应外使之例，交涉文书须归一员主持。", process: "1844年起以两广总督兼办理五口通商事务，设署于广州，耆英、徐广缙、叶名琛先后任之，专司与各口领事往来文书、条约交涉与通商税则之事，不隶六部，亦无定品；1859年移驻上海，1861年总理各国事务衙门设立后渐废。", impact: "此制使对外交涉在中央行政体系之外，凭个人风格而成，叶名琛之于粤案即坐此；总理衙门成立后交涉权始回收于中枢，近代外交部之雏形由此而生，其间十七年的空白实为历次争端扩大的制度原因。", figures: ["耆英","叶名琛"], place: "广东广州（今广州）", state: "清", sources: ["《（道光）筹办夷务始末》","《清史稿·职官志》与《筹办夷务始末》凡例","丁名楠等《帝国主义侵华史》第一卷"], tags: ["通商大臣","外交体制"] }, related: ["cn--1844--p01", "cn--1861--i01"] },
  { id: "cn--1844--p04", track: "cn", year: 1844, yearApprox: false, dim: "politics", weight: 2, title: "冯云山入紫荆山", summary: "以塾师入炭户，会众至数千。", detail: { background: "拜上帝会在广东传教不得人，洪秀全归花县设馆，冯云山愿入广西山区。", process: "1844年底冯云山入广西桂平紫荆山，以设馆授徒、雇工为便，渐得曾玉珍、杨秀清、萧朝贵等山民与烧炭户；至1847年，会众三千余人，立条规、禁偶像，其势力出于官府控制之外。", impact: "紫荆山的客民、炭户由此成为太平军最早的骨干，会馆与营制即其组织雏形；清方仅以教匪视之，地方士绅则以团练相抗，1847年有押解冯云山入狱之案，冲突终至不可收拾。", figures: ["冯云山","杨秀清","萧朝贵"], place: "广西桂平紫荆山（今桂平）", state: "清", sources: ["韩山文《太平天国起义记》","《李秀成自述》","罗尔纲《太平天国史》"], tags: ["拜上帝会","广西"] }, related: ["cn--1843--p02", "cn--1847--p01"] },
  { id: "cn--1845--i01", track: "cn", year: 1845, yearApprox: false, dim: "institution", weight: 4, title: "《上海土地章程》公布", summary: "界石一下，遂有界内之政。", detail: { background: "《虎门条约》许英人在口租地建屋，英国首任领事巴富尔与苏松太道宫慕久议定界址章程。", process: "1845年11月上海道公布《上海土地章程》二十三款，以洋泾浜以北、李家庄以南为准，英租界约八百三十亩；定华洋分处、界内道路桥梁由领事与道台会同经理，1846、1848年美法相继定界。", impact: "此为在华第一个租界章程，界内渐立警捕、捐税、司法与市政机关，成国中之国；1854年小刀会事起后领事代征关税、设工部局与巡捕房，租界遂为近代中国财政、治安与外交纠纷的长期病灶。", figures: ["宫慕久","巴富尔"], place: "江苏上海（今上海）", state: "清", sources: ["王铁崖编《中外旧约章汇编》第一册","《上海公共租界工部局董事会会议录》","徐公肃《上海公共租界制度》"], tags: ["租界","土地章程"] }, related: ["cn--1843--e01", "cn--1854--p01"] },
  { id: "cn--1845--p01", track: "cn", year: 1845, yearApprox: false, dim: "politics", weight: 2, title: "广州反入城风潮", summary: "绅团罢市，官不能制夷亦不能制民。", detail: { background: "《江宁条约》未明许英人入广州城，义律、德庇时屡请入城，耆英以暂缓相推。", process: "1845至1849年，粤省绅商以团练、揭帖力拒英人入城，南海、佛山各乡联团，铺户罢市；耆英一面弹压民团、一面搪塞外使，1847年英人以兵船胁逼一度入城，1849年再逼城，因兵力不继而止。", impact: "此事使英国断定须向北京索取修约与公使驻京，而粤民之强与官府之弱并形于中外记载；广东自此会党、械斗与外交冲突相错，清廷对该省之控制力大减，咸丰初年洪兵围城即在此局中发生。", figures: ["耆英","德庇时"], place: "广东广州（今广州）", state: "清", sources: ["《（道光）筹办夷务始末》卷七九","梁廷枏《夷氛闻记》","马士《中华帝国对外关系史》卷一"], tags: ["入城问题","团练"] }, related: ["cn--1841--m03", "cn--1849--p01"] },
  { id: "cn--1846--p01", track: "cn", year: 1846, yearApprox: false, dim: "politics", weight: 3, title: "亚马留改制澳门", summary: "葡官征税封关，华官失其柄。", detail: { background: "澳门自1557年以来由香山县丞、澳门同知管华民，葡人自治其夷目之事。", process: "1846年4月葡署总督亚马留到任，宣布澳门为自由港，向华民征捐税、清理田亩、封关截饷，驱逐清朝官吏；两广总督耆英以羁縻处之不敢用兵，1849年8月亚马留为乡民沈志亮等刺杀，葡人遂据望厦、凼仔。", impact: "澳门的华界之治自此名存实亡，清方仅守空名；此事与五口通商并进，使沿海地面管辖权不断流失，中葡关于澳门的正式条约则迟至1887年方成，其间四十余年为既成事实之积累期。", figures: ["亚马留","耆英"], place: "广东澳门（今澳门）", state: "清", sources: ["《（道光）两广总督奏折》与《香山县志》","黄文钜《澳门港史研究》","马士《中华帝国对外关系史》卷一"], tags: ["澳门","亚马留"] }, related: ["cn--1845--i01"] },
  { id: "cn--1846--p02", track: "cn", year: 1846, yearApprox: false, dim: "politics", weight: 2, title: "紫荆山毁像与教民构讼", summary: "废祠祀、夺庙产，乡里遂成两造。", detail: { background: "会众日多而祠庙、神会之费出于其家，入会者不祀祖先神佛，与亲族乡里成讼。", process: "1846年前后紫荆山会众撤毁庙宇神像、夺会款以充公用，山脚六陈村等团练与曾作新等生员屡禀县控，而县令以会众跨三县、不敢办；洪秀全时往来花县、浔州之间，与冯云山相会定规。", impact: "拜上帝会与地方社会的决裂至此不可合，官府既不能弹压又不能抚绥，山内客民依违两间；教民与非教民之分成为太平军与清军对峙时的社会界线，亦是此后数十年两广、贵州、云南分类冲突之旧辙。", figures: ["洪秀全","冯云山"], place: "广西桂平（今桂平）", state: "清", sources: ["韩山文《太平天国起义记》","《（咸丰）广西巡抚周天爵奏稿》","罗尔纲《太平天国史》"], tags: ["团练","教民"] }, related: ["cn--1844--p04", "cn--1848--p01"] },
  { id: "cn--1847--x01", track: "cn", year: 1847, yearApprox: false, dim: "explore", weight: 3, title: "契约华工出洋之始", summary: "招工之馆设于口岸，猪仔之贩日起。", detail: { background: "五口开埠后，西、葡、荷、美招工者在澳门、厦门设馆，以预付船资与合同为饵。", process: "1847年由厦门、澳门开船，载契约华工往古巴哈瓦那种植园，为华工有整批出洋之始；1850年代厦门一港岁出以千计至万人，船中拥挤、病死与被虐者十常三四，招工馆与拐贩、口岸地方官相为市。", impact: "此为近代最大一次海外移民潮之始，其后二十余年间数十万人散及南洋、美洲，筑铁路、开矿山、种棉蔗；其惨苦激起的抗议与各国招工章程，使清廷在1860年条约中首次被迫面对人口输出之规制，华侨亦由此成为近代中国与外部世界的重要一环。", figures: ["耆英"], place: "福建厦门、广东澳门", state: "清", sources: ["英国议会《关于华工贸易之报告》","陈达《南洋华侨与闽粤社会》","《（咸丰）筹办夷务始末》"], tags: ["苦力","华侨"] }, related: ["cn--1849--e01", "cn--1851--m01"] },
  { id: "cn--1847--p01", track: "cn", year: 1847, yearApprox: false, dim: "politics", weight: 3, title: "冯云山系狱与洪秀全赴粤营救", summary: "一狱而会权旁移。", detail: { background: "紫荆山会众毁像、夺会款，山脚士绅与官府相讼，桂平地方以教匪科之。", process: "1847年秋，桂平生员王作新率团练捕冯云山、卢六解县狱，以结盟颠倒官府拟罪；洪秀全闻讯赴广州营救，上禀两广总督，狱留而不决，1848年初赖曾玉珍等具保得释，会中事暂交杨秀清、萧朝贵主之。", impact: "冯云山入狱的数月使会内主持之责落于杨、萧，二人遂有代天父、天兄传言之举，宗教权力由创会者转入居者之手；1856年天京内讧之根源，实伏于此狱数月之间。", figures: ["冯云山","洪秀全","杨秀清","王作新"], place: "广西桂平、广东广州", state: "清", sources: ["韩山文《太平天国起义记》","《李秀成自述》","罗尔纲《太平天国史》"], tags: ["拜上帝会","狱案"] }, related: ["cn--1848--p01", "cn--1856--m02"] },
  { id: "cn--1848--c01", track: "cn", year: 1848, yearApprox: false, dim: "culture", weight: 4, title: "《瀛寰志略》成书", summary: "写五大洲政体，并颂华盛顿。", detail: { background: "徐继畬（1795—1873）字健南，山西五台人，1842年后历任闽浙一带道府与巡抚，在厦门、广州从美国传教士雅裨理处询问外国事情。", process: "1848年《瀛寰志略》十卷成于福建官署，图四十余幅，述五大洲各国山川、政事、教宗与军制，于美国推华盛顿不设王侯之号、不循世及之序，谓几与三代之世英雄所以得天下者同，于英国议会兵制记之尤详。", impact: "此书与《海国图志》并为同光士夫认识世界之两据，总理衙门与同文馆皆尝取资；其称西国之善触时讳，1850年代御史据以劾奏，徐氏旋以闽案落职，足见道咸之际对外认识所受的政治压力。", figures: ["徐继畬","雅裨理"], place: "福建（今福州）", state: "清", sources: ["徐继畬《瀛寰志略》自序","《清史稿·徐继畬传》","《（咸丰）东华录》"], tags: ["瀛寰志略","世界知识"] }, related: ["cn--1842--c01", "cn--1840--c01"] },
  { id: "cn--1848--p01", track: "cn", year: 1848, yearApprox: false, dim: "politics", weight: 4, title: "天父天兄下凡", summary: "传言代兴，会权移于杨萧。", detail: { background: "冯云山系狱、洪秀全赴粤营救，紫荆山会众动摇，赖杨秀清、萧朝贵弹压。", process: "1848年杨秀清以天父下凡代传言、萧朝贵以天兄下凡代传言，当众发号令、责会众怠慢，洪秀全归而承认其言为神旨；自此天父传言可申君权，东王令旨出于天父，军师之制渐具。", impact: "神权与创会者权威的分离，是太平天国政治结构的根本缺陷：杨秀清得以下凡节制洪秀全，1856年天京内讧之祸即伏于此；同时下凡之言成为动员山民、整肃会纪的有效手段，起事之众由数千增至数万。", figures: ["杨秀清","萧朝贵","洪秀全"], place: "广西桂平（今桂平）", state: "清", sources: ["《天父下凡诏书》","韩山文《太平天国起义记》","罗尔纲《太平天国史》"], tags: ["天父下凡","权力结构"] }, related: ["cn--1847--p01", "cn--1856--m02"] },
  { id: "cn--1849--p01", track: "cn", year: 1849, yearApprox: false, dim: "politics", weight: 3, title: "广州拒入城，耆英内召", summary: "民团罢市而兵舰退，主和者失其据。", detail: { background: "耆英以暂缓入城搪塞英国，粤省绅民怒其欺民以媚外，揭帖遍城埠。", process: "1849年春英舰再逼广州城，粤民闭城罢市，南海、番禺诸乡团练数万人守堵，巡抚黄恩彤主守；英国以兵力不足、恐陷于群众而止，入城之议搁置，耆英旋召入京，以办理不得体责之。", impact: "中英双方由此得出相反的教训：清方与粤民以为民威可却夷，英方则判定须与北京直接交涉，遂有修约、公使驻京之要求；广东官民两失其柄，会党与土客之斗亦在此局中长大，咸丰四年洪兵围城即其结果。", figures: ["黄恩彤","文咸","耆英"], place: "广东广州（今广州）", state: "清", sources: ["《（道光）筹办夷务始末》卷八七","梁廷枏《夷氛闻记》","马士《中华帝国对外关系史》卷一"], tags: ["入城问题","团练"] }, related: ["cn--1845--p01", "cn--1854--p01"] },
  { id: "cn--1849--m01", track: "cn", year: 1849, yearApprox: false, dim: "military", weight: 2, title: "会剿拜上帝会无功", summary: "三县交界之贼，官兵不能办。", detail: { background: "桂平、平南、武宣、象州交界山区为会众渊薮，官府以十家牌、团练防堵。", process: "1849年夏，广西巡抚郑祖琛调官兵、团练分区搜捕，会众避入紫荆、风门山麓，清军将帅互不调度，仅获零星会众；洪秀全、冯云山往来平在山、花县之间，会众以进贡、团营相结，人数反增。", impact: "广西一省之兵不能制数千山民，暴露绿营调遣、饷需与考课之制全不足恃；清廷乃许地方自办团练、劝捐济军，兵权财权下移之机已动，其后曾国藩在籍办团练、湘淮勇营代绿营而兴，其端皆在桂平山中数载之间。", figures: ["郑祖琛","洪秀全"], place: "广西桂平、武宣（今桂平、武宣）", state: "清", sources: ["《（道光）广西巡抚郑祖琛奏稿》","《（咸丰）东华录》","罗尔纲《太平天国史》"], tags: ["绿营","团练"] }, related: ["cn--1851--m02", "cn--1853--i01"] },
  { id: "cn--1849--a01", track: "cn", year: 1849, yearApprox: false, dim: "art", weight: 2, title: "广州外销画之盛", summary: "十三行画棚，写口岸与百工。", detail: { background: "自乾隆末广州画工以油彩、水彩为欧人作肖像与船景，十三行、河南一带画棚并立。", process: "1840年代关乔昌（啉呱）及其一门画室以西洋画法成通商口岸、官吏服制、百工百艺与港景图册，销伦敦、波士顿、纽约，年输出以千百计；其同时与照相术初入粤并存，画中之虎门、省河、行商建筑细节可与他种记载互证。", impact: "外销画是中国最早面向海外市场的实用美术，也是鸦片战争前后中西视觉互观的直接材料，近年为艺术史与城市史研究者据以复原十三行与口岸社会；其业至1860年代为照相馆所代，画人多转入摄影与广告画。", figures: ["关乔昌"], place: "广东番禺（今广州）", state: "清", sources: ["伦敦国家海事博物馆藏外销画册","（近人）《中国外销画图录》","（清）《澳门纪略》续编"], tags: ["外销画","十三行"] }, related: ["cn--1757--e01", "cn--1843--e01"] },
  { id: "cn--1849--e01", track: "cn", year: 1849, yearApprox: false, dim: "economy", weight: 2, title: "厦门苦力贸易之成市", summary: "招工馆与猪仔行，列于海澄口岸。", detail: { background: "1847年首批契约华工出洋后，西属古巴、荷属南洋与秘鲁招工者续至闽粤口岸。", process: "1849年前后厦门、汕头、澳门招工馆林立，华工以预付船资与三年契约相抵，出洋之数岁增至数千；船上拥挤、疫死与虐待之案叠出，1852年厦门有华工暴起杀招工馆人之事，英方据此派舰护馆，地方官以涉外案件处之。", impact: "苦力贸易使闽粤沿海乡村失了数千至数万壮年劳力，也带来侨汇与海外同乡组织；清方对人口输出既不能禁亦不能护，遂至1860年中英、中法条约明定华工出洋章程，国家第一次以条约形式承认并规制国民之海外劳工流动。", figures: ["耆英"], place: "福建厦门（今厦门）", state: "清", sources: ["英国议会《关于华工贸易之报告》","陈达《南洋华侨与闽粤社会》","《（咸丰）筹办夷务始末》"], tags: ["苦力","出洋"] }, related: ["cn--1847--x01", "cn--1860--p02"] },
  { id: "cn--1850--p01", track: "cn", year: 1850, yearApprox: false, dim: "politics", weight: 3, title: "宣宗崩，文宗即位", summary: "新诏先诛权佞，中外有更新之望。", detail: { background: "宣宗晚年事皆循例，穆彰阿以军机领枢廷垂二十年，言路多所顾忌。", process: "1850年2月宣宗崩，皇四子奕詝即位，改元咸丰；侍读周祖培、御史多隆阿等先后指陈壅蔽之弊，乃革穆彰阿职、琦善获遣戍，追复林则徐、邓廷桢原官，一时士论快之，谓有道咸更化之象。", impact: "新朝以除权佞、昭雪前臣收拾人心，然太平军已在广西团营，河、漕、盐三政俱困，将帅无人；咸丰一朝之内乱外患并至而中枢无更张之力，仅以督抚用人、地方筹捐因应，兵权财权下移遂成终清之局。", figures: ["奕詝","穆彰阿","周祖培"], place: "京师（今北京）", state: "清", sources: ["《清宣宗实录》卷四八五","《清文宗实录》卷二","《（咸丰）东华录》"], tags: ["咸丰即位","更化"] }, related: ["cn--1851--m01", "cn--1850--f01"] },
  { id: "cn--1850--p02", track: "cn", year: 1850, yearApprox: false, dim: "politics", weight: 4, title: "拜上帝会团营金田", summary: "解产赴营，别男女而立馆。", detail: { background: "洪秀全、冯云山定计起事，先以天父之言诏会众团营，避清吏之搜捕。", process: "1850年夏秋，洪秀全密令桂平、贵县、武宣、象州、平南各处会众赴金田团营，凡金银田产尽解公库、通财均食，男女分馆，七月初十日大团营；至十一月，团营者约一万至二万人，其中壮丁数千，清广西巡抚周天爵、提督向荣等调兵防堵。", impact: "团营与圣库之制把宗教团体一变而为军事共产之组织，其男女分营、通财均食之法行军时犹沿用；清方仅以教匪目之，地方官互相推诿，遂使会众完成集结，1851年正月正式建号起事。", figures: ["洪秀全","杨秀清","冯云山","萧朝贵"], place: "广西桂平金田村（今桂平）", state: "清", sources: ["《天父下凡诏书》","《贼情汇纂》","罗尔纲《太平天国史》"], tags: ["团营","圣库"] }, related: ["cn--1851--m01", "cn--1849--m01"] },
  { id: "cn--1850--f01", track: "cn", year: 1850, yearApprox: false, dim: "figure", weight: 2, title: "林则徐卒于潮州途中", summary: "再拜钦差，未至军而殁。", detail: { background: "林则徐自伊犁起用，历陕甘总督、巡抚陕西、广西巡抚，1849年以病解职回闽。", process: "1850年11月清廷拜林则徐为钦差大臣赴广西督办军务，自福建航海至广东潮汕，11月22日卒于普宁途次，年六十六，谥文忠；遗折论边患，谓不系西海强邻则为北海俄罗斯，为后来言防俄者所常称。", impact: "其人进退死生恰与道咸之际外交内乱相始终：主战则得罪于和议，再起则已在军兴之后；清廷最后一名有系统外情与海防认识的大员既殁，此后办夷务者多以敷衍为事，而广西之役一寄之赛尚阿、和春辈。", figures: ["林则徐"], place: "广东普宁（今普宁）", state: "清", sources: ["《林文忠公政书》","《清史稿·林则徐传》","杨国桢《林则徐传》"], tags: ["林则徐","道咸时局"] }, related: ["cn--1842--f01", "cn--1850--p01"] },
  { id: "cn--1851--m01", track: "cn", year: 1851, yearApprox: false, dim: "military", weight: 5, title: "金田起事，建号太平天国", summary: "竖旗发难，十四年兵端自此。", detail: { background: "团营既成，会众与清兵在金田、江口叠次交锋，清军参将纪正明等被歼。", process: "1851年1月11日（道光三十年十二月初十日）洪秀全三十八岁生日，杨秀清传天父旨，金田正式起事，建号太平天国、元辛开，编伍两卒旅师军之制；五月于象州中平山破清军，提督罗绕光战死，9月突围北上，25日克永安州（今蒙山）。", impact: "起事由地方教乱转为建国之战，清军在广西连丧提镇，绿营不可用之状尽露，于是有在籍官绅办团练之诏，湘淮勇营之局由此而开；此后十四年战祸遍及十八省，为清代人口、财源与地方权力结构的转折点。", figures: ["洪秀全","杨秀清","萧朝贵","赛尚阿"], place: "广西桂平金田（今桂平）", state: "清", sources: ["《太平天国文书汇编》","《贼情汇纂》","罗尔纲《太平天国史》"], tags: ["金田起义","太平天国"] }, related: ["cn--1850--p02", "cn--1851--p01"] },
  { id: "cn--1851--p01", track: "cn", year: 1851, yearApprox: false, dim: "politics", weight: 4, title: "永安建制封五王", summary: "五王并立而听于东王。", detail: { background: "太平军克永安州后驻守半载，整军纪、定官制历法与礼制。", process: "1851年12月洪秀全诏封杨秀清为东王、萧朝贵西王、冯云山南王、韦昌辉北王、石达开翼王，并受东王节制，诏明各王俱受东王节制，兵马调度、兵器粮秣皆听东王签发；又定《太平礼制》、颁天历，设六官丞相、检点、指挥诸职。", impact: "军师负责制使宗教神权与君权并立，封王之序与权力之实不相称，为1856年内讧之张本；同时官制、军制、礼制粗具，拜上帝会由会党一变而为政权，其官阶、地名与避讳之繁，亦成为后世考订太平文书之凭。", figures: ["洪秀全","杨秀清","冯云山","石达开"], place: "广西永安州（今蒙山）", state: "清", sources: ["《太平礼制》与《天父下凡诏书》二集","《贼情汇纂》","罗尔纲《太平天国史》"], tags: ["永安建制","封王"] }, related: ["cn--1851--m01", "cn--1856--m02"] },
  { id: "cn--1851--m02", track: "cn", year: 1851, yearApprox: false, dim: "military", weight: 3, title: "清军大营之溃与将帅获罪", summary: "号兵数万，一战而丧提镇。", detail: { background: "清以大学士赛尚阿为钦差大臣督师，调绿营四集，饷需浩大而兵未更事。", process: "1851年至1852年初，清军连败于独松山、永安外围，提督祥康、总兵长瑞等先后被议罪，将帅各保营地、文武互讦；永安一陷，赛尚阿以纵贼出岭逮京治罪，两广、湖广、江南防务节节溃坏。", impact: "围剿之败使清廷承认绿营不能当大敌，乃有在籍办团练、捐厘济军之政，兵权财权自是下移；咸丰中督抚专兵与湘淮将帅之兴，以及地方以厘养兵之局，皆以此数败为始。", figures: ["赛尚阿","向荣","周天爵"], place: "广西桂平、永安至湖南", state: "清", sources: ["《（咸丰）东华录》","《清史稿·赛尚阿传》","罗尔纲《太平天国史》"], tags: ["绿营","钦差大营"] }, related: ["cn--1851--m01", "cn--1853--i01"] },
  { id: "cn--1851--s01", track: "cn", year: 1851, yearApprox: false, dim: "science", weight: 3, title: "《全体新论》刊行", summary: "以解剖说脏腑，中医之论始遭质。", detail: { background: "合信自1849年在上海、厦门行医，以眼科与外科取得信用，遂译西医形质之书。", process: "1851年合信所译《全体新论》刊于广州，述骨节、血脉、脏腑、脑髓之形质与功用，附图说，并据亲验解剖以论呼吸、血液循环；其后《西医略论》《内科新说》《妇婴新说》相继刊行。", impact: "此书为近代第一部系统汉译西医人体学，与《医林改错》之争由此而起，中国传统脏腑、经络之说第一次在解剖证据前被要求改口；江南制造局翻译馆续译医书、同光间中西医并立之议与教会医院之兴，皆以此数种为发端。", figures: ["合信"], place: "广东广州（今广州）", state: "清", sources: ["合信《全体新论》","王清任《医林改错》","《格致汇编》"], tags: ["西医","解剖"] }, related: ["cn--1843--e01", "cn--1865--s01"] },
  { id: "cn--1852--m01", track: "cn", year: 1852, yearApprox: false, dim: "military", weight: 3, title: "蓑衣渡之败，冯云山死事", summary: "入楚第一战，丧其谋主。", detail: { background: "太平军自永安围城中突围，循山路东北行，欲入湖南以取沿江之地，清军追蹑其后。", process: "1852年6月3日太平军经广西全州蓑衣渡，楚北提督余万清不守，知县江忠源以练勇先据其地，斩木塞河、伏炮两岸；太平军船触木阻伏，南王冯云山中炮死，将士溺毙被斩者数百人，遂弃道州南下。", impact: "冯云山为拜上帝会之实际组织者，其死使会中再无可以平衡杨秀清、韦昌辉之人，永安封王之序从此空出一格；江忠源以湖南练勇挫其前锋，亦开此后湘军以乡里之兵当大敌之路。", figures: ["冯云山","江忠源","余万清"], place: "广西全州蓑衣渡（今广西全州）", state: "清", sources: ["张德坚《贼情汇纂》","王闿运《湘军志》","罗尔纲《太平天国史》"], tags: ["蓑衣渡","冯云山"] }, related: ["cn--1851--p01", "cn--1852--m02"] },
  { id: "cn--1852--m02", track: "cn", year: 1852, yearApprox: false, dim: "military", weight: 4, title: "太平军围长沙不克", summary: "攻坚八月，西王中炮而殒。", detail: { background: "太平军由道州、郴州入湖南，欲得长沙为根本之地，清方调绿营、团练四集，省城戒严。", process: "1852年9月至11月太平军围长沙八十余日，西王萧朝贵以偏师先到、中炮死于南门城外；清以张亮基、江忠源守城，曾国藩时在长沙帮办团练，城中兵民死伤与疫病并作；11月30日太平军夜半弃围北走，取益阳、岳州，遂有入鄂之势。", impact: "长沙不克是太平军由流动转向攻坚失败的开端，萧朝贵之死又失一宿将；此后沿江疾下，水营之船多取之于岳州、武昌，湘军水师之谋由此而起，湖南全省自此为两方必争之地。", figures: ["萧朝贵","张亮基","江忠源","曾国藩"], place: "湖南长沙（今湖南长沙）", state: "清", sources: ["《（咸丰）东华录》","王闿运《湘军志》","罗尔纲《太平天国史》"], tags: ["长沙","攻坚"] }, related: ["cn--1852--m01", "cn--1853--m01"] },
  { id: "cn--1853--m01", track: "cn", year: 1853, yearApprox: false, dim: "military", weight: 4, title: "太平军克武昌，沿江东下", summary: "一城再陷，舟师万艘。", detail: { background: "太平军得岳州缴获民船数千只，水营始立，顺流而下，湖广兵单不可御。", process: "1853年1月12日太平军克武昌，巡抚常大淳死之，城中官署民房被焚者万计；2月由汉阳、武昌东下，号众五十万，船万余艘，连陷黄州、蕲州、九江、安庆，3月抵江宁城下，沿途清军多望风而溃。", impact: "长江自武汉至金陵尽为太平军所有，清廷之漕路、盐路与腹地通讯同时中断，安徽一省城池十陷八九；江南大营、江北大营之设与后来湘军东下，皆以夺回此段江面为前提。", figures: ["常大淳","杨秀清","林凤祥"], place: "湖北武昌至江苏江宁", state: "清", sources: ["张德坚《贼情汇纂》","《（咸丰）东华录》","罗尔纲《太平天国史》"], tags: ["武昌","水营"] }, related: ["cn--1853--m02", "cn--1852--m02"] },
  { id: "cn--1853--m02", track: "cn", year: 1853, yearApprox: false, dim: "military", weight: 5, title: "太平军克江宁，建为天京", summary: "得金陵而有国都，南北对峙成。", detail: { background: "太平军东下水陆并进，杨秀清定取金陵之议，清两江总督陆建瀛守江宁而前军先溃。", process: "1853年3月19日太平军破仪凤门入江宁外城，将军祥康死之，29日洪秀全自水西门入城，改江宁为天京，以为小天堂；城中驻防城被攻，八旗兵民之被杀与散走者，清方奏报与近人考订之数自数万至十余万不等，至今估计相悬。", impact: "自此有都城、有制度、有赋税之局，与清廷划江而峙，江南三省财富出入尽受威胁；咸丰朝用兵以江南、江北大营为主而二十年不能下此城，兵、财、权之下移与湘淮军之兴，皆以此为动力。", figures: ["洪秀全","杨秀清","向荣","祥康"], place: "江苏江宁（今江苏南京）", state: "清", sources: ["《太平天国文书汇编》","《金陵癸甲纪事略》","《（咸丰）东华录》"], tags: ["天京","定都"] }, related: ["cn--1853--i01", "cn--1853--m01"] },
  { id: "cn--1853--i01", track: "cn", year: 1853, yearApprox: false, dim: "institution", weight: 5, title: "颁《天朝田亩制度》", summary: "凡天下田，天下人同耕。", detail: { background: "定都天京后太平以立法为务，杨秀清主持其事，其制出于拜上帝会圣库之法与《周礼》之想。", process: "1853年冬颁《天朝田亩制度》，以户计口，不论男女，分田为九等、受田配多寡，二十五家设一两司马；产物除足口粮外悉归国库，婚丧、孤寡、兵备皆由库出，兼立乡官、乡兵与礼拜之制。", impact: "此制因其绝对平均之法从未真正推行，占领区实际以「照旧缴粮纳税」代之；然其为近代中国第一份以平均土地为纲的公开纲领，戊戌以后论社会革命者多举之，1920年代以来的土地纲领亦尝自认承其统绪，此为其最大历史影响。", figures: ["杨秀清","洪秀全"], place: "江苏天京（今江苏南京）", state: "清", sources: ["《天朝田亩制度》原文，载《太平天国文书汇编》","张德坚《贼情汇纂》","罗尔纲《太平天国史》"], tags: ["天朝田亩制度","土地纲领"] }, related: ["cn--1853--m02", "cn--1859--i01"] },
  { id: "cn--1853--f01", track: "cn", year: 1853, yearApprox: false, dim: "figure", weight: 4, title: "曾国藩在籍办团练", summary: "一介礼部侍郎，开湘军之局。", detail: { background: "曾国藩（1811—1872）湖南湘乡人，道光进士，官至礼部右侍郎，1852年底以母忧回籍守制。", process: "1853年正月奉上谕帮办湖南团练，以长沙设局，汰绿营之冗、募乡农为勇，以科举同年与宗族乡里关系相维系，王鑫、罗泽南、李续宾诸生员起于乡间；1854年起造战船、训练水师，二年而成湘军水陆数万。", impact: "督抚专兵、以勇营代绿营之局自是而开，饷需出于厘金与捐输而不仰户部，兵将相习而成私属；其后淮军、北洋皆沿此式，清代权力结构由内重外轻转为外重内轻，实以此为转关。", figures: ["曾国藩","左宗棠","罗泽南"], place: "湖南长沙、湘乡（今湖南长沙、湘乡）", state: "清", sources: ["《曾国藩全集·奏稿》","王闿运《湘军志》","黎庶昌《曾文正公年谱》"], tags: ["湘军","团练"] }, related: ["cn--1854--i02", "cn--1861--i01"] },
  { id: "cn--1853--m03", track: "cn", year: 1853, yearApprox: false, dim: "military", weight: 4, title: "太平军北伐", summary: "师出安徽，两年而覆于直隶。", detail: { background: "天京既立，杨秀清遣偏师北上，意在撼动京师、分江南之兵。", process: "1853年5月林凤祥、李开芳率两万余人自浦口北伐，经安徽、河南渡河入山西，转掠直隶；1854年2月前锋抵天津西南之静海、独流，与僧格林沁、胜保相持，绝粮被围；1855年3月林凤祥被执送京师凌迟，李开芳陷于山东冯官屯，俱遇害。", impact: "北伐以孤军深入而无后继，为太平战略上最大之失；同时清廷震惧，直隶、山东防务大坏，僧格林沁以蒙古骑兵为京畿柱石，其起用与后来歼捻之任皆由于此。", figures: ["林凤祥","李开芳","僧格林沁","胜保"], place: "江苏浦口至直隶静海（今南京、天津）", state: "清", sources: ["《（咸丰）东华录》","《清史稿·僧格林沁传》","罗尔纲《太平天国史》"], tags: ["北伐","孤军"] }, related: ["cn--1853--m02", "cn--1855--m01"] },
  { id: "cn--1853--m04", track: "cn", year: 1853, yearApprox: false, dim: "military", weight: 3, title: "太平军西征", summary: "夺安庆上游，与湘军相持三年。", detail: { background: "天京既立，杨秀清以江西、湖广为上游客食之所，遣军溯江西向。", process: "1853年5月胡以晃、曾天养等自安庆西征，连克庐州、九江，1854年入湖北、湖南，与曾国藩水陆相争于岳州、靖港；1854年4月靖港之败曾国藩几自经，1855年初石达开取湖口，湘军水师为之一挫。", impact: "西征使太平天国得安徽、江西之粮与盐路，天京之食半仰于此；湘军则因败而改制，水师立、陆营分，十年后以安庆为攻坚之的，其规模皆起于西征战事。", figures: ["胡以晃","曾天养","石达开","曾国藩"], place: "安徽、江西、湖北", state: "清", sources: ["王闿运《湘军志》","张德坚《贼情汇纂》","罗尔纲《太平天国史》"], tags: ["西征","湘军"] }, related: ["cn--1855--m01", "cn--1853--f01"] },
  { id: "cn--1853--p01", track: "cn", year: 1853, yearApprox: false, dim: "politics", weight: 3, title: "上海小刀会起事", summary: "占县城十七月，租界因之坐大。", detail: { background: "天地会支派小刀会在沪上游勇、船夫、商贩中传习，闽、粤会众分籍互竞，清吏不能制。", process: "1853年9月7日刘丽川、林阿福等率小刀会袭占上海县，囚苏松太道，设大明国于县署，分遣占青浦、南汇、嘉定，与太平天国通声气而不受其节制；英法美军与清兵合围，1855年2月17日城陷，刘丽川突围被杀。", impact: "起事期间中国地方机关瓦解，英法美领事借代征税、管道路与巡捕，租界之市政、警政与司法权由此坐大，1854年设委员会收税、后来会审公廨之制皆以此次为凭；苏松一带富人避入租界，华人地产与商业遂为租界扩张之实。", figures: ["刘丽川","吴健彰"], place: "江苏上海（今上海）", state: "清", sources: ["《小刀会资料汇编》","《（同治）上海县志》","马士《中华帝国对外关系史》卷一"], tags: ["小刀会","上海"] }, related: ["cn--1854--i01", "cn--1853--i02"] },
  { id: "cn--1853--i02", track: "cn", year: 1853, yearApprox: false, dim: "institution", weight: 3, title: "江南江北大营之设", summary: "两营围城，兵权寄于将帅。", detail: { background: "江宁既失，清廷以向荣、琦善分统大军，南北夹击天京，不复责成地方督抚。", process: "1853年3至4月向荣建江南大营于江宁城外孝陵卫，琦善建江北大营于扬州城外，两营兵各号数万，专防金陵、镇扬一带，将帅得专折奏事而不隶督抚；1856年6月天京内讧后江南大营乘乱进逼，1856年8月营垒溃于东门，1858年江北大营再溃。", impact: "两营之制使中枢直接统兵而饷需全仰各省协济，绿营之糜烂与提镇之跋扈并见；其后两营俱溃、苏常震动，朝廷不得不倚曾国藩、左宗棠以湘淮之兵规复东南，督抚专兵专饷之势自此不可复返。", figures: ["向荣","琦善","杨秀清"], place: "江苏江宁孝陵卫、扬州", state: "清", sources: ["《（咸丰）东华录》","《钦定平定粤匪方略》","罗尔纲《太平天国史》"], tags: ["大营","兵制"] }, related: ["cn--1853--m02", "cn--1856--m02"] },
  { id: "cn--1854--i01", track: "cn", year: 1854, yearApprox: false, dim: "institution", weight: 4, title: "外人代征江海关税", summary: "一关之税，归领事自雇其人。", detail: { background: "小刀会占上海县，江海关监督道署毁弃，英法美三国领事以护商为名自任税务。", process: "1854年6月29日英法美水兵占江海关，道台不能理事，三国领事各聘英美人收税，立协定章程，外国船报关付单与货样皆归其自行经理；1855年吴健彰雇美人司税务而所得须偿洋人垫付，1859年英人李泰国署理总税务司，1861年后各地新开之关依此制推行。", impact: "中国海关行政权由是旁落于外人之手，而关税信用反因此确立，抵缴赔款与后来的外债、洋款担保皆取给于此；同一机关在代收税则之外又办邮务、航政、教育与译书诸端，为近代中国财政与外交最复杂之一制。", figures: ["李泰国","吴健彰"], place: "江苏上海（今上海）", state: "清", sources: ["《（咸丰）筹办夷务始末》","马士《中华帝国对外关系史》卷一","《海关十年报告》近代史所译本"], tags: ["海关","税务司"] }, related: ["cn--1853--p01", "cn--1861--e01"] },
  { id: "cn--1854--p01", track: "cn", year: 1854, yearApprox: false, dim: "politics", weight: 4, title: "三国公使天津修约之请", summary: "十六款之请，格于督抚而不达于朝。", detail: { background: "1843、1844诸约许十二年后可相商更改，英法美于1852至1854年先后照会请修约。", process: "1854年6至7月英国公使包令、法国公使布尔布隆、美国公使麦莲抵白河赴天津，直隶总督桂良以钦差办夷务与之晤商，所请为公使驻京、增开口岸、内地行船通商、改定税则、鸦片弛禁等十余款，清廷以碍难允行为辞一律拒绝，三国无兵而退。", impact: "第一次修约失败使英法认定须以兵力促成之方针；至1856年亚罗号事发，英法即以修约与换约为名义，第二次鸦片战争之因在此数年间累积而成；清方于拒绝的同时未作任何战备，其后条约所失十倍于此时所拒。", figures: ["包令","桂良","布尔布隆","麦莲"], place: "直隶天津（今天津）", state: "清", sources: ["《（咸丰）筹办夷务始末》","王铁崖编《中外旧约章汇编》第一册","马士《中华帝国对外关系史》卷一"], tags: ["修约","天津"] }, related: ["cn--1844--p01", "cn--1856--m01"] },
  { id: "cn--1854--i02", track: "cn", year: 1854, yearApprox: false, dim: "institution", weight: 5, title: "厘金之创", summary: "值百抽一之商税，以济军需。", detail: { background: "军兴饷绌，户部不能拨解，帮办安徽军务雷以诚在扬州一带筹捐自给。", process: "1854年前后雷以诚于仙女庙等镇设局，行值百抽一之制，分货物通过之活厘与行商坐贾之捐二途，遇卡抽以济江北大营之饷；其后曾国藩、胡林翼移之于湖南、江西，各省仿行，同治间岁入四千余万两。", impact: "厘金为晚清财政第一大新税，其得在于不仰户部而能养兵，其失在于局卡林立、商货重征、抽捐之权散于将帅地方；半个多世纪中屡有裁厘之请而不能，至1931年裁厘改税，中国国内商税之梗由此而成。", figures: ["雷以诚","曾国藩","胡林翼"], place: "江苏扬州仙女庙（今江苏江都）", state: "清", sources: ["《（咸丰）东华录》","《清史稿·食货志》","罗玉东《中国厘金史》"], tags: ["厘金","财政"] }, related: ["cn--1853--f01", "cn--1860--p02"] },
  { id: "cn--1855--d01", track: "cn", year: 1855, yearApprox: false, dim: "disaster", weight: 5, title: "铜瓦厢河决，黄河北徙", summary: "大河改道，清代河患之局终。", detail: { background: "黄河自明以来南分流淮、以漕济运，至道光以后祥符、北岸迭决，河身日高；1855年河南兰阳铜瓦厢当河之险。", process: "1855年8月（咸丰五年六月十九日）黄河北岸河南兰阳铜瓦厢（今兰考东北）大决，初决续堵不竣而再溃，水东北趋曹州、郓城，冲张秋、穿运河，夺山东大清河故道，经济北、利津入海；时值用兵，库绌不能复堵，仅河南山东各修岸堤自守。", impact: "河由借淮入海改为独流入北海，是1128年以来河道的又一次大徙，亦为清代最后一次；淮河北股断流，下游六七十州县成河淤滩地，山东直隶河南水患格局自此重定；运河被冲、河运遂废，漕粮全归海运，治河之费与河督之权同日而衰。", figures: ["庚长"], place: "河南兰阳铜瓦厢（今河南兰考）", state: "清", sources: ["《清史稿·河渠志》","《再续行水金鉴》","《（咸丰）东华录》"], tags: ["铜瓦厢","黄河改道"] }, related: ["cn--1841--d01", "cn--1855--m02"] },
  { id: "cn--1855--m01", track: "cn", year: 1855, yearApprox: false, dim: "military", weight: 3, title: "石达开取湖口，湘军水师再挫", summary: "一窗之锁，内外水师两分。", detail: { background: "曾国藩于九江、湖口设内外水师，以巨舰扼鄱阳湖口，石达开继西征之局来争。", process: "1855年1月31日（咸丰四年十二月十三日）太平军夜袭湖口，以小船纵火、横索塞江，曾国藩座船被夺，内湖一军尽覆，追至九江再破外江师；曾移驻南昌，收集残船重编，彭玉麟、杨载福分领水师，自此不复以巨舰深入。", impact: "湖口之捷使太平军保住九江、湖口、安庆一线，天京上游粮路得通近三年；湘军由是悟水陆相依、步步稳进之法，改小炮船、立陆师四路，十年后以长围取安庆，其兵法之变实起于此一败。", figures: ["石达开","曾国藩","彭玉麟","胡以晃"], place: "江西湖口、九江", state: "清", sources: ["王闿运《湘军志》","《曾国藩全集·奏稿》","罗尔纲《太平天国史》"], tags: ["湖口","水师"] }, related: ["cn--1853--m04", "cn--1855--d01"] },
  { id: "cn--1855--m02", track: "cn", year: 1855, yearApprox: false, dim: "military", weight: 3, title: "淮北诸捻推张乐行为盟主", summary: "聚众结旗，捻事自此成局。", detail: { background: "咸丰初黄河屡决、淮北州县连年荒旱，盐枭、贫农纠众掠食，皖北蒙城、亳州、宿州各处捻党互为首目，无所统一。", process: "1855年秋张乐行、龚得树等聚各路捻党于安徽蒙城、亳州之间，张乐行被推为盟主，号大汉，立五旗军制，以纵横为走、不守城邑；其众时合时分，与太平军、苗沛霖各军声息相通，咸丰五年至同治五年之间为患皖豫山东直隶。", impact: "捻由分散的抢掠团体转为有盟主、旗制之军，牵制清军北上之兵力，使江南大营溃后清廷两面并用兵；僧格林沁歼石达开余部、尾追黄捻皆由此起，1865年僧格林沁死于曹州，淮军代之，遂成剿捻之局。", figures: ["张乐行","龚得树"], place: "安徽蒙城、亳州", state: "清", sources: ["《（咸丰）东华录》","《清史稿·张乐行传》","中国史学会编《捻军》"], tags: ["捻军","淮北"] }, related: ["cn--1865--m01", "cn--1855--d01"] },
  { id: "cn--1855--p01", track: "cn", year: 1855, yearApprox: false, dim: "politics", weight: 2, title: "贵州台拱苗民以抗粮起事", summary: "一隅抗粮，全省糜烂十七年。", detail: { background: "贵州田赋素重，屯土弁索取无艺，台拱厅苗民连年控诉不得直；太平军兴后协饷改派，加征益甚。", process: "1855年春（咸丰五年二月）贵州台拱厅（今台江）苗民张秀眉、李洪谋等以抗粮起事，四出攻堡，与古州、下司厅屯苗响应，旋据清江、台拱、丹江一带；同时贵州号军、教军、回民各处并起，省城文报几不通。", impact: "张秀眉部据黔东南达十七年，至1872年为席宝田所平；贵州一省自咸丰至同治兵事不绝，户口损折、田亩抛荒，甲于西南，协饷反受于他省，成为晚清最贫之一省，其善后屯政与改流余绪延至光绪之季。", figures: ["张秀眉","李洪谋","席宝田"], place: "贵州台拱厅（今贵州台江）", state: "清", sources: ["《清实录·咸丰朝》","《（光绪）贵州通志》","《清史稿·席宝田传》"], tags: ["苗民起事","贵州"] }, related: ["cn--1856--p01", "cn--1855--d01"] },
  { id: "cn--1856--m01", track: "cn", year: 1856, yearApprox: false, dim: "military", weight: 4, title: "亚罗号事件与英军轰广州", summary: "一旗之辱，遂启六年之战。", detail: { background: "1856年广州官宪搜捕艇上的海盗与水手，英籍船亚罗号悬旗被扯，两广总督叶名琛持约拒其领事入城会商。", process: "1856年10月8日广东水师登搜泊于十三行前之亚罗号，扯下英旗，捕十二人，英领事巴夏礼照会索交凶犯并道歉，叶名琛仅解还九人而不予其要求；10月21日起英兵登岸占大黄岗炮台，10月25日炮轰广州城，12月焚英、美、法商馆，法国以传教士马神尚被杀案与之合兵。", impact: "巴麦尊内阁借此案定下以兵力促成修约之策，1857年派额尔金、葛罗为专使，第二次鸦片战争之名义由此而起；叶名琛不战不和、不备不求援之处置，使广东一省在两年内自溃，中外记载对其评断至今未一。", figures: ["叶名琛","巴夏礼","包令"], place: "广东广州（今广州）", state: "清", sources: ["《（咸丰）筹办夷务始末》","《叶名琛档案》","马士《中华帝国对外关系史》卷一"], tags: ["亚罗号","广州"] }, related: ["cn--1854--p01", "cn--1857--m01"] },
  { id: "cn--1856--m02", track: "cn", year: 1856, yearApprox: false, dim: "military", weight: 5, title: "天京内讧，杨秀清、韦昌辉继死", summary: "两王相杀，国势由是而衰。", detail: { background: "杨秀清以天父下凡总揽军政，屡辱洪秀全及诸王，1856年夏逼封万岁，洪秀全密召在江西之韦昌辉回京。", process: "1856年9月2日（咸丰六年八月初五）韦昌辉率众入城杀东王杨秀清及其家属，两月之内株连被杀者自数千至二万余说不等，清方奏报与私家记载互异；石达开自武汉归京责其滥杀，韦昌辉并欲图之，石达开夜缒出城，阖门老幼尽遇害；11月2日洪秀全杀韦昌辉及其党，传首各省，旋追念杨秀清、复其封号。", impact: "内讧使太平天国失去最后的统筹之才与百战之众，从此再无可以一其号令之人；洪秀全以幼西王洪仁发、洪仁达摄政，将帅各自为部，李秀成、陈玉成虽起而无统一之令，江南、江西之局五年之内尽溃，为太平兴亡之第一大转关。", figures: ["杨秀清","韦昌辉","石达开","洪秀全"], place: "江苏天京（今江苏南京）", state: "清", sources: ["《李秀成自述》","《（咸丰）东华录》","罗尔纲《太平天国史》"], tags: ["天京内讧","太平天国"] }, related: ["cn--1853--i02", "cn--1857--p01"] },
  { id: "cn--1856--m03", track: "cn", year: 1856, yearApprox: false, dim: "military", weight: 3, title: "太平军破江南江北大营", summary: "两营俱溃，围天京之师瓦解。", detail: { background: "向荣之江南大营、吉尔杭阿之江北大营分扼金陵、镇江，围城三载而饷绌兵骄。", process: "1856年6月秦日纲督陈玉成、李秀成自浦口东下，先破江北大营于扬州，江苏巡抚吉尔杭阿自杀于高资；7月2日回师趋孝陵卫，纵火焚江南大营连营数十座，向荣退奔丹阳，9月病死，清军失粮械无算。", impact: "两营之溃使清廷在京师之外再无可以居中节制之师，只能责成在籍官绅之湘军与绿营提镇，东南之兵权、饷权自此尽归外重；此役虽为太平军事之顶点，两月后即遇内讧，所得旋即弃之。", figures: ["秦日纲","向荣","吉尔杭阿","陈玉成"], place: "江苏扬州、江宁孝陵卫", state: "清", sources: ["《（咸丰）东华录》","《钦定平定粤匪方略》","罗尔纲《太平天国史》"], tags: ["江南大营","江北大营"] }, related: ["cn--1853--i02", "cn--1856--m02"] },
  { id: "cn--1856--p01", track: "cn", year: 1856, yearApprox: false, dim: "politics", weight: 3, title: "云南官练屠回，迤西尽乱", summary: "一省之杀，回汉相残十余年。", detail: { background: "云南自乾隆以来汉回杂处，厂矿、市集恒有仇杀；咸丰初地方官以办团练防苗、防捻为名，练阀与回寨互斗，楚雄、临安先见兵。", process: "1856年9月底（咸丰六年八月中旬）巡抚舒兴阿与在籍官绅倡省城及各府州县团练同时杀回，昆明一日死者以千计，通省被杀之数自万余至数万不等，奏报与私家记载互异，舒兴阿旋被议处；迤西回民由是尽起，汉寨回寨各筑城自固。", impact: "云南自是兵事十七年，大理杜文秀、澂江马德新、迤东马如龙各为一局，同治年间岑毓英以抚回、用回收功，人口田亩损折甲于西南；此祸与贵州苗事、陕甘回事相续，成为晚清西南、西北边政与财政之大患。", figures: ["舒兴阿","杜文秀","马德新"], place: "云南昆明、楚雄、大理", state: "清", sources: ["《清实录·咸丰朝》","中国史学会编《回民起义》","《（光绪）云南通志》"], tags: ["云南回变","团练"] }, related: ["cn--1856--m04", "cn--1862--m03"] },
  { id: "cn--1856--m04", track: "cn", year: 1856, yearApprox: false, dim: "military", weight: 3, title: "杜文秀建幕府于大理", summary: "据迤西一隅，自号元帅。", detail: { background: "云南迤西回民被官练搜杀之后四出奔命，赵州、邓川、大理一带无所属，众推保山回生杜文秀主军。", process: "1856年11月（咸丰六年十月）迤西各股回民克大理府城，推杜文秀为总统兵马大元帅，立幕府，蓄发易服、奉太平天国正朔而不受其节制，禁掠、均赋、重农桑、通商旅，兼用汉绅回掌，五年内取楚雄、普洱诸城，与昆明相持十余年；1867至1868年大举围省城不下。", impact: "大理政权以回汉并用、保护商旅立国，十七年间自成一制，为清代西南最大之变；1872年（同治十一年）大理不守，杜文秀服毒，部众被屠杀者数万（清方奏报与近人考订之数互异），云南田畴荒芜、汉回相猜延及百年。", figures: ["杜文秀","马德新"], place: "云南大理（今大理）", state: "清", sources: ["中国史学会编《回民起义》","《清史稿·岑毓英传》","《（民国）大理县志》"], tags: ["杜文秀","大理政权"] }, related: ["cn--1856--p01", "cn--1872--m01"] },
  { id: "cn--1857--m01", track: "cn", year: 1857, yearApprox: false, dim: "military", weight: 4, title: "英法联军陷广州，叶名琛被掳", summary: "两日而失省会，督臣走死海外。", detail: { background: "英额尔金、法葛罗率海陆军至澳门会齐，照会入城修约，叶名琛不设备、不请援，省城兵仅四千。", process: "1857年12月28日英法军炮击广州城，29日攀城而入，督署尽陷，两广总督叶名琛被掳，1858年解往加尔各答，1859年4月死焉；总督柏贵随之受傀儡之局，广东巡抚抚局由外人、领事与汉奸合署，时称三年。", impact: "中国一省会城为外国远征军所取，督臣被掳，此在清代未有，各省自此确知城不可守；英法得以广州为基地，北上扰天津、大沽，1858年四国条约之局成；而广东官绅倡议团练自办夷务，民间排外与买办并行，为后来历次教案之先声。", figures: ["叶名琛","额尔金","葛罗","柏贵"], place: "广东广州、虎门", state: "清", sources: ["《（咸丰）筹办夷务始末》","马士《中华帝国对外关系史》卷一","《东华录》咸丰朝"], tags: ["广州","第二次鸦片战争"] }, related: ["cn--1856--m01", "cn--1858--p01"] },
  { id: "cn--1857--p01", track: "cn", year: 1857, yearApprox: false, dim: "politics", weight: 3, title: "石达开出走，别领一军", summary: "翼王去国，师遂无统一之令。", detail: { background: "天京内讧后石达开以元佐之功还朝，而洪秀全忌之，任二王兄洪仁发、洪仁达以制其权，达开不能安。", process: "1857年6月石达开率精锐数万自天京出走，驻安庆，别立将幕不复奉天京节制，转战江西、浙江、福建、湖南、广西、贵州、四川，至1863年5月在大渡河紫打地（今四川石棉）覆灭；太平军自此仅有陈玉成、李秀成两军各守一方。", impact: "石达开之去使天京失去最后的统帅与上游之众，安徽、江西两年内继溃，其孤军流动作战而不能立根据地，卒陷于大渡河；李秀成自述以任王兄、疑功臣、诸王各自雄长为亡国之首由，此局实为洪杨体制之果。", figures: ["石达开","洪秀全","洪仁玕"], place: "江苏天京、安徽安庆", state: "清", sources: ["《李秀成自述》","罗尔纲《太平天国史》","《（同治）四川通志》"], tags: ["石达开","出走"] }, related: ["cn--1856--m02", "cn--1863--m01"] },
  { id: "cn--1857--s01", track: "cn", year: 1857, yearApprox: false, dim: "science", weight: 3, title: "《几何原本》后九卷译竣", summary: "两千年之书，至是始全。", detail: { background: "明万历时利玛窦、徐光启仅译前六卷而辍业，其后二百五十年无人续之。", process: "1856至1857年李善兰与英国传教士伟烈亚力在上海墨海书馆续译欧几里德《几何原本》后九卷（卷七至卷十五），合前六卷为十五卷完书，1858年刻成行世；李善兰并自撰《垛积比类》《尖术辨变》，以中算之垛积、天元相证微积之说。", impact: "全书既备，算学遂为输入西学之门户，同文馆、江南制造局译书之局皆由此路进来；李善兰自后与伟烈亚力续译代数学、微积分、重学、光学诸书，微分、积分、代数、函数、系数等中文术语多出其手，近世中文数学语言自兹定名。", figures: ["李善兰","伟烈亚力","徐光启"], place: "上海墨海书馆（今上海）", state: "清", sources: ["《几何原本》后九卷李善兰序","《则古昔斋算学》","伟烈亚力《中国学术述略》"], tags: ["几何原本","西学输入"] }, related: ["cn--1607--s01", "cn--1859--s01"] },
  { id: "cn--1857--f01", track: "cn", year: 1857, yearApprox: false, dim: "figure", weight: 2, title: "魏源卒于杭州", summary: "一部《海国图志》，东传遂有其书。", detail: { background: "魏源（1794—1857）湖南邵阳人，道光进士，官至高邮知州，与林则徐、龚自珍同主经世之学，以《圣武记》《海国图志》名世。", process: "1855年魏源以高邮弃城被劾免职，此后寓杭州；1857年5月（咸丰六年四月）卒于城南僧舍，年六十四，临终犹以所著《元史新编》未定为念，身后其书由子承旷、门人董理刻行。", impact: "《海国图志》师夷长技以制夷之议，在中国因鸦片战后讳言夷务而少传，在日本自1854年起训点翻刻者数十种，佐其幕末维新之论；至1860年代中国设制造局、遣出使之使，始追认此书为先声，一书在中日两国接受之迟速相反，最为论近代思想传播者所据。", figures: ["魏源","林则徐","龚自珍"], place: "浙江杭州（今杭州）", state: "清", sources: ["《魏源集》","《清史稿·魏源传》","《海国图志》原序"], tags: ["魏源","经世之学"] }, related: ["cn--1842--c01", "cn--1841--f01"] },
  { id: "cn--1858--m01", track: "cn", year: 1858, yearApprox: false, dim: "military", weight: 3, title: "英法北犯，失大沽炮台", summary: "海口一破，议约于兵轮之侧。", detail: { background: "广州既陷，英法照会修约而以兵北指，1858年4月四国兵船二十余艘北驶大沽，直隶总督谭廷襄驻天津防堵，兵单器旧。", process: "1858年5月20日英法陆战队自塘沽上岸，以轮船轰炮台、陆兵抄其后路，南北两岸炮台俱陷，守兵死事者数百、失炮二百余尊（清方奏报与外方记载多寡互异），联军之死数十人；22日兵轮入河抵天津城下，桂良、花沙纳奉命为钦差大臣赴津议约。", impact: "大沽一失，京师之门无险可守，和战之权尽入敌手，四国之约皆成于炮口之下；而清廷于换约之时犹不自备战，1859年拒其入北河、1860年再败，所失遂不止于天津条约一款。", figures: ["谭廷襄","桂良","花沙纳","额尔金"], place: "直隶大沽、天津（今天津）", state: "清", sources: ["《（咸丰）筹办夷务始末》","《清史稿·谭廷襄传》","马士《中华帝国对外关系史》卷一"], tags: ["大沽","天津"] }, related: ["cn--1858--p01", "cn--1859--m01"] },
  { id: "cn--1858--p01", track: "cn", year: 1858, yearApprox: false, dim: "politics", weight: 5, title: "中英、中法《天津条约》订立", summary: "公使驻京，十口通商，鸦片名洋药。", detail: { background: "桂良、花沙纳至天津，英使额尔金、法使葛罗以兵为质，限五日定约，所递之国书一字不许改。", process: "1858年6月26日、27日中英、中法《天津条约》先后订于天津，其大端为各国公使驻京、增开牛庄、登州、台南、淡水、潮州、琼州、汉口、九江、南京、镇江十口通商、教士准入内地传教、英人赔四百万两、法人赔二百万两、更定税则值百抽五，并许鸦片以洋药名目进口纳税。", impact: "公使驻京一款破清代以礼部、理藩院待外邦之旧局，十年之内遂有总理衙门；十口之开使外力由沿海五口沿江西入内地，并及台湾、琼州；鸦片弛禁由此名正言顺，其后进口岁逾六万箱，白银外流与吸食之众不复可问，为禁烟二十年之结果。", figures: ["桂良","花沙纳","额尔金","葛罗"], place: "直隶天津（今天津）", state: "清", sources: ["王铁崖编《中外旧约章汇编》第一册","《（咸丰）筹办夷务始末》","马士《中华帝国对外关系史》卷一"], tags: ["天津条约","五口至十口"] }, related: ["cn--1858--m01", "cn--1860--p02"] },
  { id: "cn--1858--p02", track: "cn", year: 1858, yearApprox: false, dim: "politics", weight: 5, title: "中俄《瑷珲条约》，割黑龙江以北", summary: "一纸而弃江北之地六十余万。", detail: { background: "1850年代俄人以黑龙江为其属境，东西伯利亚总督穆拉维约夫数遣兵船载哥萨克顺江而下至庙街屯堡，趁英法兵起以为可胁。", process: "1858年5月28日黑龙江将军奕山与穆拉维约夫在瑷珲立约：黑龙江以北、外兴安岭以南六十余万平方公里之地归俄，乌苏里江以东至海约四十万平方公里为中俄共管，黑龙江左岸六十四屯居民仍旧住业，只准中俄船只行于江面；奕山初拒之，俄兵船环逼且绝其援路，遂为画押。", impact: "此约使中国失外兴安岭以南大半之地，吉林自此无海口，俄得两江航路与滨海之区；清廷虽将奕山交部议处而未之改，1860年《北京条约》遂并乌苏里江以东追认之；封禁之东北由是开关禁，光绪朝俄日相争于满洲，其根皆在此两约。", figures: ["奕山","穆拉维约夫","伊格那提耶夫"], place: "黑龙江瑷珲（今黑龙江黑河）", state: "清", sources: ["王铁崖编《中外旧约章汇编》第一册","《清史稿·奕山传》","《（咸丰）筹办夷务始末》"], tags: ["瑷珲条约","东北疆界"] }, related: ["cn--1858--p01", "cn--1860--p03"] },
  { id: "cn--1858--p03", track: "cn", year: 1858, yearApprox: false, dim: "politics", weight: 2, title: "中美《天津条约》与华工出洋", summary: "自愿出口之条，开苦力之市。", detail: { background: "美国专使列卫廉先英法而定约，以最惠之条坐享各国所得，别求通行内地与传教、招工之利。", process: "1858年6月18日中美《天津条约》三十款立于天津，许华民与外国人立约自愿出洋做工、船只遭风得入中国口岸修理、教士入内地传教、领事得会审华民之案，而明定拐卖之禁；1860年英法《北京条约》又以华工出口入约。", impact: "契约华工由此得法律之名，1859年起英法在汕头、澳门设招工馆，1860至1870年代出洋华工前后数十万（通行估计自四十万至五十万），古巴、秘鲁、荷属东印度之种植园赖其工；拐卖、超载、虐遇之案不绝，1874年秘鲁钦查群岛案发之后，1877年中国始与秘鲁订护工之约。", figures: ["列卫廉","桂良"], place: "直隶天津（今天津）", state: "清", sources: ["王铁崖编《中外旧约章汇编》第一册","陈翰笙编《华工出国史料汇编》","《（咸丰）筹办夷务始末》"], tags: ["华工","条约口岸"] }, related: ["cn--1847--x01", "cn--1860--p02"] },
  { id: "cn--1858--m02", track: "cn", year: 1858, yearApprox: false, dim: "military", weight: 3, title: "三河之捷，李续宾一军尽覆", summary: "湘军第一覆军，皖局为之再棘。", detail: { background: "1858年秋李续宾率湘军精锐自皖北连下太湖、桐城诸城，进图庐州，兵单而进，陈玉成求救于李秀成。", process: "1858年11月陈玉成合捻军张乐行之众攻三河湘军营垒，李秀成自庐江来援，两军内外合击，湘军八千人（一说五千）尽覆，李续宾战死，曾国华死之，桐城、太湖之师退驻英山；胡林翼闻耗哭之，上疏自劾，曾国藩累日不御酒肉。", impact: "三河之役为湘军兴起以来第一次覆军，安徽之局由是再棘，天京之围暂解；洪秀全以功任将，陈玉成、李秀成并王而各统其众；曾国藩自此定不孤军深入、不分兵攻城之长围渐缩之法，十年后攻安庆一循此说。", figures: ["陈玉成","李秀成","李续宾","胡林翼"], place: "安徽三河镇（今肥西）", state: "清", sources: ["王闿运《湘军志》","《胡林翼集》","罗尔纲《太平天国史》"], tags: ["三河","湘军"] }, related: ["cn--1858--p01", "cn--1861--m01"] },
  { id: "cn--1859--m01", track: "cn", year: 1859, yearApprox: false, dim: "military", weight: 3, title: "僧格林沁却英舰于大沽", summary: "一胜而召更大之败。", detail: { background: "天津条约既成，清以桂良改议税则，欲免公使驻京、添开口岸诸款；英使普鲁斯坚持入北河换约，僧格林沁奉旨大修大沽台。", process: "1859年6月25日英海军提督何伯率炮舰十二艘强行驶入河口，僧格林沁已于河口横铁链木栅、增炮位至三十余、暗垒相望，台上先发制之，搁浅三舰被击毁，登岸陆战队死伤五百余人，英军溃退，法舰一受创；清军伤亡数十人（两方所报互异）。", impact: "此为鸦片战争以来中国之胜仗，而其果为更大之败：英国内阁以二千万镑、法国以三千万法郎之费大举报复，命克灵顿、蒙托邦各将一军，1860年兵至二万而北塘无守，天津、京师之祸皆以此役为名。", figures: ["僧格林沁","何伯","普鲁斯"], place: "直隶大沽（今天津）", state: "清", sources: ["《（咸丰）筹办夷务始末》","《清史稿·僧格林沁传》","马士《中华帝国对外关系史》卷一"], tags: ["大沽","换约"] }, related: ["cn--1858--m01", "cn--1860--m01"] },
  { id: "cn--1859--i01", track: "cn", year: 1859, yearApprox: false, dim: "institution", weight: 4, title: "洪仁玕入觐，上《资政新篇》", summary: "太平天国仿西立国之全书。", detail: { background: "石达开出走之后天京无人可任，洪仁玕（1822—1862）久居香港、上海，通英文而知外国制度，1859年夏间入天京。", process: "1859年洪仁玕至天京，封干王、加军师之号，上《资政新篇》：请设新闻官、书信馆、银行、保险、火车、轮船、矿政、医院、育婴之养、罪人之工，以法制吏而不用严刑，许富者设厂雇工，与各邦通商而不许其强传其教，并请与熟谙外国事务者相见讲求；洪秀全逐条批是其议，交各王核议。", impact: "此为近代中国第一份仿西立国的全盘纲领，早于总理衙门与江南制造局两年；然当时战事方棘、诸王多不措意，一事未行，书中银行、火车、矿政诸议至1870至1890年代乃渐次见于实行；与《天朝田亩制度》并读，一主平均、一主资本，而皆以无其地与其人俱废。", figures: ["洪仁玕","洪秀全"], place: "江苏天京（今江苏南京）", state: "清", sources: ["《资政新篇》原文，载《太平天国文书汇编》","《洪仁玕自述》","罗尔纲《太平天国史》"], tags: ["资政新篇","仿西之政"] }, related: ["cn--1853--i01", "cn--1861--i01"] },
  { id: "cn--1859--s01", track: "cn", year: 1859, yearApprox: false, dim: "science", weight: 2, title: "《代微积拾级》译刻成书", summary: "微积分始有中文之名。", detail: { background: "李善兰自1852年入上海墨海书馆，与伟烈亚力共译《几何原本》后九卷既毕，复取微分积分之书续译。", process: "1859年李善兰、伟烈亚力据英国罗密士之微积分教本译成《代微积拾级》十八卷，以代数解几何之法、立微分积分之式，同年并译《圆锥曲线说》三卷；李氏自撰《垛积比类》《尖术辨变》，以中算垛积、天元相证微积之说。", impact: "微积分之书至是始有中文，微分、积分、变数、函数、系数、指数、有理、无理诸名皆定于李善兰之手，至今不易；同文馆、江南制造局译书之例与京师大学堂算学教本皆沿此书，近代中文科学语汇由此开端。", figures: ["李善兰","伟烈亚力","罗密士"], place: "上海墨海书馆（今上海）", state: "清", sources: ["《代微积拾级》原序","李善兰《则古昔斋算学》","李迪《中国数学史》"], tags: ["代微积拾级","算学翻译"] }, related: ["cn--1857--s01", "cn--1868--s01"] },
  { id: "cn--1860--m01", track: "cn", year: 1860, yearApprox: false, dim: "military", weight: 3, title: "联军自北塘登陆，大沽再失", summary: "登陆无阻，炮台复陷。", detail: { background: "1859年大沽之败后英法大举调兵，1860年6月英军万余、法军七千余集结上海，7月北驶，俄使伊格那提耶夫亦至，劝清弃大沽而不听。", process: "1860年8月初联军于北塘登陆无阻，中旬连陷塘沽、新河，下旬水陆合攻大沽南北炮台，北岸炮台破，总兵邵灿死之，直隶总督恒福先退守天津、旋以罪逮问；僧格林沁退通州布防，联军遂入天津。", impact: "大沽、天津再失，京师之藩篱尽去；恒福以先退获罪而不能赎其失，诸军不相救、炮械不敌并见，恭亲王奏请议抚之疏由是再上；而清廷于使臣入京、换约礼节仍力持其说，至十数日之后园寝被焚而后定。", figures: ["僧格林沁","恒福","邵灿","额尔金"], place: "直隶北塘、大沽、天津", state: "清", sources: ["《（咸丰）筹办夷务始末》","《清史稿·僧格林沁传》","马士《中华帝国对外关系史》卷一"], tags: ["北塘","大沽"] }, related: ["cn--1859--m01", "cn--1860--m02"] },
  { id: "cn--1860--m02", track: "cn", year: 1860, yearApprox: false, dim: "military", weight: 2, title: "八里桥之败，马队不复振", summary: "冷兵当热器，一战而决。", detail: { background: "联军既登陆，僧格林沁以蒙古马队当野战之任，驻通州、八里桥一线，议者以其长于平原冲击。", process: "1860年9月21日（咸丰十年八月初七）僧格林沁督马队自八里桥、曹甸三进扑法军之阵，法军炮队横击、英军循运河而进，马队死伤枕藉而不能近；是日清军伤亡逾千，联军之死不过数十（两方报数互异），22日通州遂陷。", impact: "冷热兵器之差至此而定，自此清廷不复议战，专主抚局；僧格林沁以马队为京畿柱石之局亦于此终，五年后死于捻事；八里桥一败使恭亲王孤守京城，园寝之焚与约款之加皆在数十日之内。", figures: ["僧格林沁","克灵顿","蒙托邦"], place: "直隶通州八里桥（今北京通州）", state: "清", sources: ["《（咸丰）筹办夷务始末》","《清史稿·僧格林沁传》","马士《中华帝国对外关系史》卷一"], tags: ["八里桥","马队"] }, related: ["cn--1860--m01", "cn--1860--p01"] },
  { id: "cn--1860--p01", track: "cn", year: 1860, yearApprox: false, dim: "politics", weight: 3, title: "文宗北狩热河", summary: "君主去国，留恭亲王任抚局。", detail: { background: "八里桥败后京师戒严，粮尚可支而战守之兵皆不足恃，朝议或有请亲征、有请巡幸者。", process: "1860年9月22日咸丰帝自圆明园启銮幸热河避暑山庄，命恭亲王奕訢以钦差大臣便宜行事留京任抚局；10月园寝被焚，11月两宫皇子在热河；1861年8月22日帝崩于烟波致爽轩，年三十一，在热河凡一年。", impact: "君主去国而宗庙宫阙尽在敌兵之下，清代声威之损无逾于此；恭亲王以抚局得与各国周旋而遂掌外交之权，为其后任议政王与总理衙门之资；幼帝立而顾命八大臣与两宫之争起，亦以山庄一年之局为因。", figures: ["奕訢","载垣","肃顺"], place: "直隶热河（今河北承德）", state: "清", sources: ["《（咸丰）东华录》","《清史稿·文宗本纪》","《（咸丰）朝上谕档》"], tags: ["北狩","热河"] }, related: ["cn--1860--m03", "cn--1861--p01"] },
  { id: "cn--1860--m03", track: "cn", year: 1860, yearApprox: false, dim: "military", weight: 5, title: "圆明园之劫与焚", summary: "三朝营建，两日而烬。", detail: { background: "圆明园历雍正、乾隆至咸丰百五十年经营，为御园之首；八里桥后，清方拘英法换约随员三十九人送京师刑部囚之。", process: "1860年10月6日至9日法军先入圆明园、英军继之，军人与随营者掠陈设库藏数日，珍籍、宋元版、金玉陶器不可胜计；英方记载谓被拘者三十九人、获释时死者二十余人，额尔金以此为由，10月18、19日命英军第一师纵火焚圆明园及静明园、静宜园、清漪园诸处，火三日不熄。", impact: "一代君园与其藏书古物同时而尽，今存遗址与散在欧美诸馆之石件画卷皆其证，被劫铜牛、虎、猴诸兽首迟至2000年、2003年始部分回国；此事在西方亦有议者，雨果1861年书简斥为劫掠，而清廷以抚局已成不敢置词，后之论外交者每举以为弱国之鉴。", figures: ["额尔金","格兰特","巴夏礼"], place: "京师圆明园（今北京海淀）", state: "清", sources: ["《（咸丰）筹办夷务始末》","马士《中华帝国对外关系史》卷一","雨果《一八六一年书简》"], tags: ["圆明园","劫掠"] }, related: ["cn--1860--p01", "cn--1860--p02"] },
  { id: "cn--1860--p02", track: "cn", year: 1860, yearApprox: false, dim: "politics", weight: 5, title: "《北京条约》成，赔款割九龙", summary: "换约于礼部，津约全行而加款。", detail: { background: "园寝既焚，恭亲王奕訢以抚局自任，俄使又以居间自功，英法限十日答复，城中议遂决。", process: "1860年10月24、25日奕訢与额尔金、葛罗在北京礼部互换《天津条约》约本，另立中英、中法《北京续增条约》：天津条约全行、增天津为通商口岸、赔英法各八百万两、准华民与外国人立约出洋做工、许耶稣天主两教传教并还其堂产，中英约又割九龙司尖沙嘴以北之地归英。", impact: "赔款一千六百万两归海关税项抵缴，外人总司税务之权因此愈重；天津开埠使京师之门长启，九龙司之割使香港之界北移至山；此约与天津条约合成一系列，此后四十年之税则、租界、领事裁判皆以此为据，论近代外交者以1858至1860年为一局。", figures: ["奕訢","额尔金","葛罗"], place: "京师（今北京）", state: "清", sources: ["王铁崖编《中外旧约章汇编》第一册","《（咸丰）筹办夷务始末》","《（咸丰）东华录》"], tags: ["北京条约","赔款"] }, related: ["cn--1858--p01", "cn--1861--i01"] },
  { id: "cn--1860--p03", track: "cn", year: 1860, yearApprox: false, dim: "politics", weight: 3, title: "中俄《北京条约》定东北、西北之界", summary: "因换约之便，并乌苏里以东。", detail: { background: "英法之役，俄使伊格那提耶夫以调停自居，旋以瑷珲之约未行为辞，请并其地而另定西路之界。", process: "1860年11月14日奕訢与俄使立中俄《北京条约》十五款：确认《瑷珲条约》，将乌苏里江以东至海之地全归俄有，定西部边界自沙宾达巴至葱岭、喀什噶尔一线，许俄人在喀什噶尔、塔尔巴哈台通商，并准俄国于北京设东正教馆、陆路通商免税。", impact: "俄国由是得滨海州与海参崴之港，吉林遂无出海之路；西北一段界址至1864年《塔城界约》、1881年《伊犁条约》依此约所指山岭河流逐段勘定，合瑷珲、北京两约前后所割，近人考订共百四十余万平方公里，诸家所计略有出入；中国北疆之形势自是不可复改。", figures: ["奕訢","伊格那提耶夫"], place: "京师（今北京）", state: "清", sources: ["王铁崖编《中外旧约章汇编》第一册","《清史稿·邦交志》","《（咸丰）东华录》"], tags: ["中俄界约","割地"] }, related: ["cn--1858--p02", "cn--1871--m01"] },
  { id: "cn--1861--i01", track: "cn", year: 1861, yearApprox: false, dim: "institution", weight: 4, title: "设总理各国事务衙门", summary: "中国始有外交之专司。", detail: { background: "《北京条约》成后，恭亲王奕訢与桂良、文祥于1861年初奏请改涉外之制，以五口通商大臣与礼部、理藩院不足以应外国常驻之使。", process: "1861年正月谕设总理各国事务衙门，以奕訢为首任大臣、桂良、文祥为大臣，初假圆明园公所，旋移京师东堂子胡同；分股办英、法、俄、美诸国交涉及传教、通商、关税、海防之政，并领同文馆、海关、铁路、矿务、出使诸端。", impact: "中国自此有主管外交与洋务之中央机关，理藩院、礼部主涉外之旧局与通商大臣之权由此收归中枢；其后四十年之制造局、船政、派使、留学之议多由此衙门而上，守旧者亦以是衙门为多事之源攻之；1901年改为外务部而列六部之上。", figures: ["奕訢","桂良","文祥"], place: "京师（今北京）", state: "清", sources: ["《（咸丰）筹办夷务始末》","《（光绪）大清会典事例》","《清史稿·文祥传》"], tags: ["总理衙门","外交机关"] }, related: ["cn--1861--p01", "cn--1862--i01"] },
  { id: "cn--1861--p01", track: "cn", year: 1861, yearApprox: false, dim: "politics", weight: 4, title: "辛酉政变，两宫垂帘听政", summary: "顾命八臣诛而后权起。", detail: { background: "1861年8月22日文宗崩于热河，遗命以载垣、端华、肃顺、景寿、穆荫、匡源、杜翰、焦祐瀛八人赞襄政务，皇后与皇子载淳生母那拉氏不得与政。", process: "两宫与恭亲王奕訢通谋，借胜保、董元醇请垂帘之奏，11月2日至京之期捕载垣、端华于宫门，遣人执肃顺于热河；载垣、端华赐自尽，肃顺弃市，余五臣革职遣戍；12月改祺祥为同治，两宫皇太后垂帘听政之制定。", impact: "此后四十余年权出西太后那拉氏之手，同治、光绪两朝之洋务、政争与甲午、戊戌、庚子之事皆以其人为枢；恭亲王任议政王并领总理衙门，中枢与外国相代之局自此而成；垂帘本清代家法所无，后之论储位、论立宪者每举为病。", figures: ["那拉氏","奕訢","肃顺","载垣"], place: "京师、热河（今北京、承德）", state: "清", sources: ["《（咸丰）东华录》","《清史稿·肃顺传》","《翁同龢日记》"], tags: ["辛酉政变","垂帘听政"] }, related: ["cn--1860--p01", "cn--1861--i01"] },
  { id: "cn--1861--m01", track: "cn", year: 1861, yearApprox: false, dim: "military", weight: 3, title: "湘军陷安庆，天京上游遂竭", summary: "地道一破，皖北无坚城。", detail: { background: "曾国藩自1860年以曾国荃吉后军长围安庆，浚长濠合围，陈玉成三次来救不克，城内粮尽。", process: "1861年9月5日湘军以地雷破安庆城，太平守将叶芸来、吴定彩部战死者万余，城中军民同遭兵火者不可计（曾国藩奏报与私家记载之数互异）；胡林翼于是月卒于武昌，曾氏遂独当其任。", impact: "安庆为天京上游之枢，一城既失，陈玉成无所归、李秀成之画江之策大左，天京但凭丹阳、句容之屏；湘军水陆东下之路始通，曾国藩即移节安庆，设内军械所而规皖南，四年后天京之局实定于此一城。", figures: ["曾国荃","陈玉成","叶芸来","曾国藩"], place: "安徽安庆（今安庆）", state: "清", sources: ["《曾国藩全集·奏稿》","王闿运《湘军志》","罗尔纲《太平天国史》"], tags: ["安庆","长围"] }, related: ["cn--1858--m02", "cn--1861--i02"] },
  { id: "cn--1861--e01", track: "cn", year: 1861, yearApprox: false, dim: "economy", weight: 3, title: "英人李泰国任总税务司", summary: "各口税务，隶于一人。", detail: { background: "1854年江海关由三国领事代征之后各口仿行，1859年清廷命英人李泰国署理总税务司，尚未专任。", process: "1861年总理衙门既设，李泰国得专任为总税务司，驻上海，各口税务司由其派委、不隶地方之官，关税支销造册报署；1863年英人赫德（1835—1911）接署，遂成三十年之局；关税岁入由五口初开时之数百万两递增至光绪季年之三千万两内外（海关报册与近人统计之数略同）。", impact: "外人总司中国海关垂五十年，其得在杜私税之弊而立借债之信用，赔款、洋款之担保皆取给于此；其失在一国税收委于外人，税司任免不关于户部，关余之拨用恒待外国之同意，为近代财政主权之大案，亦为海关统计与邮政、航政之始基。", figures: ["李泰国","赫德"], place: "上海、京师（今上海、北京）", state: "清", sources: ["马士《中华帝国对外关系史》卷二","《海关十年报告》近代史所译本","《（咸丰）筹办夷务始末》"], tags: ["总税务司","海关财政"] }, related: ["cn--1854--i01", "cn--1861--i01"] },
  { id: "cn--1861--i02", track: "cn", year: 1861, yearApprox: false, dim: "institution", weight: 3, title: "安庆设内军械所，自造火器", summary: "不假外人工料，中国兵工之始。", detail: { background: "安庆既克，曾国藩以中国之兵非火器不足以当外国，而外购之器价重而不能用、不能修，遂议自造。", process: "1861年9月曾国藩于安庆设内军械所，募无锡徐寿、金匮华蘅芳等至局，自造枪炮弹药，不假外国工师与材料，故名内军械所；1862年徐寿依西书造蒸汽机模型成，遂议造轮船，1864年局随军移江宁。", impact: "此为中国自办兵工之始，亦官办工业之第一步；1865年江南制造局继之而起，福州船政、天津机器局相承，四十年洋务皆以曾氏此局为源头；徐寿、华蘅芳由造器而译书，开江南制造局翻译馆之例，西学输入与工业自立始并为一事。", figures: ["曾国藩","徐寿","华蘅芳"], place: "安徽安庆（今安庆）", state: "清", sources: ["《曾国藩全集·奏稿》","《清史稿·徐寿传》","《格致汇编》所记制造始末"], tags: ["内军械所","自造火器"] }, related: ["cn--1861--m01", "cn--1865--s01"] },
  { id: "cn--1861--f01", track: "cn", year: 1861, yearApprox: false, dim: "figure", weight: 1, title: "胡林翼卒于武昌官署", summary: "湘军财政之立法者早逝。", detail: { background: "胡林翼（1812—1861）湖南益阳人，翰林出身，出为湖北按察使、巡抚，以恢复武昌之功实授巡抚。", process: "1860年胡林翼闻母丧，诏令夺情留任，遂请终制不得，感疾益深；1861年（咸丰十一年）八月十七日卒于武昌官署，年五十，谥文忠；此前荐左宗棠、李鸿章，定湘军东下之策，以厘金、关税自立军需。", impact: "胡林翼治鄂以理财养兵为本，江汉关与厘局之入尽归军兴之用，为湘军财政之立法者；既卒，湖北之局一转而为左宗棠、李鸿章辈崛起之地，曾国藩失其最力之援，论咸同中兴人物者以曾胡并称，而胡之早死为湘系兵财之局最大变数。", figures: ["胡林翼","曾国藩","左宗棠"], place: "湖北武昌（今武汉）", state: "清", sources: ["《胡林翼集》","《清史稿·胡林翼传》","《（咸丰）东华录》"], tags: ["胡林翼","湘军财政"] }, related: ["cn--1858--m02", "cn--1861--m01"] },
  { id: "cn--1862--i01", track: "cn", year: 1862, yearApprox: false, dim: "institution", weight: 3, title: "京师同文馆开学", summary: "官设西文之学自此始。", detail: { background: "《天津条约》定公使驻京之款，总理衙门既设，交涉日繁而中国无通外国文字之人，翻译恒出于买办与教士。", process: "1862年6月京师同文馆开馆于北京，先立英文馆，选八旗年少子弟十余人肄业，延英人包尔腾充首任英文教习；同年继增法文、俄文二馆，馆中给廪饩，课程以西文为主而兼讲算学、化学与万国公法。", impact: "同文馆为清政府所设第一所西式学堂，其教习丁韪良、欧礼斐之伦任译书与讲习，馆中学生毕业者多为驻外使署与海关之翻译参赞；1866年议增天文算学一馆而廷议大哗，1898年并入京师大学堂，凡三十六年而新学之基已成。", figures: ["奕訢","包尔腾"], place: "京师（今北京）", state: "清", sources: ["《（同治）东华录》","丁韪良《同文馆考略》","《清季中外关系史料》"], tags: ["同文馆","新式学堂"] }, related: ["cn--1861--i01", "cn--1867--c01"] },
  { id: "cn--1862--m01", track: "cn", year: 1862, yearApprox: false, dim: "military", weight: 3, title: "淮军借轮船东援上海", summary: "三日而千里，兵随火轮以行。", detail: { background: "1861年底太平军克杭州、陷苏常，上海震动，绿营不足以守，江浙官绅间道乞师于曾国藩。", process: "1862年4月李鸿章统淮勇六千五百人自安庆借英商火轮船东下，数日抵上海，为中国军队乘轮船运输之始；李鸿章旋实授江苏巡抚，以饷出于上海关税与厘金，招常胜军、置洋枪炮，与英法会防。", impact: "淮军由是代绿营与湘军而兴，上海之财、外国之器与淮人之兵三者相合，李鸿章任事由此始，其后北洋、外交、铁路、矿务皆出其手；江南之局自湘移淮，湘淮并立之势至是成。", figures: ["李鸿章","曾国藩","郭嵩焘"], place: "安徽安庆至江苏上海", state: "清", sources: ["《李鸿章全集·奏稿》","《曾国藩全集·奏稿》","《（同治）东华录》"], tags: ["淮军","轮船运兵"] }, related: ["cn--1862--m02", "cn--1861--m01"] },
  { id: "cn--1862--m02", track: "cn", year: 1862, yearApprox: false, dim: "military", weight: 3, title: "太平军攻上海不克", summary: "租界共守，沪围顿解。", detail: { background: "1861年底李秀成取苏州、杭州，兵锋及于上海之郊，城中官绅设中外会防局，请英法兵自保。", process: "1862年1月太平军前军抵上海县属之七宝、龙华，2月租界公开守界，5至6月淮军会同英法军与常胜军反攻高桥、周浦、柘泽，太平军失利；6月李秀成奉洪秀全严诏回援天京，沪围顿解。", impact: "上海自此为中外共守之地，租界之兵权、税权愈固而华人地产、商业并其繁盛，苏松富户之迁沪实成此后都会之基；太平军失苏松之税与出海之路，江南之局不复可为，淮军亦因是役尽改洋枪炮。", figures: ["李秀成","李鸿章","华尔"], place: "江苏上海、苏州", state: "清", sources: ["《李秀成自述》","《（同治）东华录》","马士《中华帝国对外关系史》卷二"], tags: ["上海之围","中外会防"] }, related: ["cn--1862--m01", "cn--1863--m02"] },
  { id: "cn--1862--m03", track: "cn", year: 1862, yearApprox: false, dim: "military", weight: 3, title: "陕甘回汉相仇，全省糜烂", summary: "一省之乱，延及十一年。", detail: { background: "太平军兴后陕西协饷加派，回汉素争田土厂矿，云南官练屠回之耗西传，团练与回寨互杀不休。", process: "1862年5至6月同州、华州、渭南团练先杀回，回众四起，西安被围经时，东路回军据潼关与太平军陈得才、蓝大顺之声息相通；清廷先后遣多隆阿、都兴阿入陕，宁、青马化龙、河州马占鳌各据一方，兵事延至1873年。", impact: "陕甘兵事十一年，人口田亩损折至重，近人据户口册报与地方志考订，同治兵燹前后陕西、甘肃人口之损各以百万计，诸家所计多寡悬绝；1873年左宗棠平肃州后以迁徙、安置、分隔回汉为善后之策，其影响延及民国之西北。", figures: ["多隆阿","马化龙","左宗棠"], place: "陕西同州、西安，甘肃宁灵", state: "清", sources: ["《（同治）陕甘方略》","曹树基《中国人口史》第五卷","《清史稿·左宗棠传》"], tags: ["陕甘回变","人口损折"] }, related: ["cn--1856--p01", "cn--1869--m01"] },
  { id: "cn--1863--m01", track: "cn", year: 1863, yearApprox: false, dim: "military", weight: 3, title: "石达开覆军于大渡河", summary: "水涨一日，孤军遂穷。", detail: { background: "石达开自安徽转战江西、湖南、广西、贵州，1863年春由云南入川南，欲取成都为根据地。", process: "1863年5月石达开军抵大渡河紫打地（今四川石棉西北），连夜涨水不能渡，土司兵袭其后，清军唐友梅、蔡步祥扼北岸；进退无路，粮尽疫作，石达开以降书乞免部众，入清营被解成都，6月受磔刑，余众多被杀散。", impact: "翼王一军之覆使太平再无成股之远征军，天京失最后之外援；其孤军流动、不立根据地而困于一水，为军事史之殷鉴，1935年中国工农红军经同一地带，论者每以石达开之覆相校。", figures: ["石达开","骆秉章","唐友梅"], place: "四川越嶲厅紫打地（今石棉）", state: "清", sources: ["《石达开供词》","《（同治）四川通志》","罗尔纲《太平天国史》"], tags: ["大渡河","紫打地"] }, related: ["cn--1857--p01", "cn--1864--m01"] },
  { id: "cn--1863--x01", track: "cn", year: 1863, yearApprox: false, dim: "explore", weight: 2, title: "容闳奉命赴美购机器", summary: "政府遣人出洋市器之始。", detail: { background: "曾国藩欲自造火器轮船而知中国无造机器之厂，非购其本不可，容闳（1828—1912）广东香山人、耶路卒业，时在曾幕。", process: "1863年容闳受曾国藩之命赴美国购办机器，经欧洲考察数月，1865年携工作机器百余种抵上海，旋存于江宁，后皆为江南制造局之基础，据容闳自述用银约六万八千两。", impact: "此为清政府第一次遣人出洋采购工业母机，江南制造局、天津机器局之器皆自此例起；容闳又建议派遣幼童出洋肄业，至1870年因天津教案得曾国藩、丁日昌会奏，1872年起四批一百二十人赴美，詹天佑、唐绍仪之伦咸出其途。", figures: ["容闳","曾国藩"], place: "美国、江苏上海", state: "清", sources: ["容闳《西学东渐记》","《曾国藩全集·奏稿》","《（同治）东华录》"], tags: ["容闳","购机"] }, related: ["cn--1865--i01", "cn--1872--x01"] },
  { id: "cn--1863--m02", track: "cn", year: 1863, yearApprox: false, dim: "military", weight: 2, title: "戈登接统常胜军", summary: "外国之将，将中国之兵。", detail: { background: "1862年9月美国人华尔攻浙江慈溪中炮死，常胜军由其友白齐文接管，骄横不奉节制。", process: "1863年白齐文以抢饷案去职，12月英国陆军军官戈登接统常胜军，饷由苏松粮台按月发给，配劈山炮、开花炮与轮船之助，随淮军攻昆山、太仓、苏州、无锡，1864年5月于苏州遣撤，戈登回国。", impact: "常胜军之制成外国军官得将其兵、外国炮舰得攻城镇之例，为后来租界驻军与联合镇压之张本；淮军因之尽弃弓矛而用洋枪，中国军队改制之议由此起；而遣撤之后洋将洋队之议又兴，李鸿章终以权不可分止之。", figures: ["戈登","华尔","白齐文","李鸿章"], place: "江苏苏州、太仓、浙江慈溪", state: "清", sources: ["《（同治）东华录》","马士《中华帝国对外关系史》卷二","《李鸿章全集·奏稿》"], tags: ["常胜军","洋将"] }, related: ["cn--1862--m02", "cn--1864--m01"] },
  { id: "cn--1864--m01", track: "cn", year: 1864, yearApprox: false, dim: "military", weight: 5, title: "湘军陷天京，太平天国亡", summary: "十四年之局，毕于一城。", detail: { background: "1863年底苏州、无锡继陷，李秀成自丹阳还天京，城中粮尽以草荐代食，洪秀全不许言转移之策。", process: "1864年6月1日洪秀全死于天京（服毒与病殁两说，曾国藩奏报据幼子之供与尸验而未能一其说），幼天王洪天贵福嗣位；7月19日曾国荃军以地雷破太平门、天京陷，城破后纵火杀伤三日，曾国藩奏称毙匪万余，私家记载谓军民被杀者自数千至数万不等，估计至今相悬；李秀成被执书供而死，洪天贵福走广德、旌德，10月被杀于南昌。", impact: "太平天国自金田至此凡十四年，其兵燹使江苏、浙江、安徽三省人口田亩损折为清代所未有，近人据户口册报与地方志考订江南人口之损在千万以上，诸家所计多寡悬绝；湘军因功而将帅遍天下，其烧杀亦为士论所讥，东南残破之后上海代苏杭为江南最大都会，此又兵事以外之大局。", figures: ["曾国荃","李秀成","洪天贵福","洪秀全"], place: "江苏天京（今江苏南京）", state: "清", sources: ["《曾国藩全集·奏稿》","《李秀成自述》","曹树基《中国人口史》第五卷"], tags: ["天京","太平天国亡"] }, related: ["cn--1853--m02", "cn--1864--f01"] },
  { id: "cn--1864--f01", track: "cn", year: 1864, yearApprox: false, dim: "figure", weight: 1, title: "洪秀全殁于围城之中", summary: "创拜上帝会者死于天京。", detail: { background: "洪秀全（1814—1864）广东花县人，屡试不第，据《劝世良言》创拜上帝会，金田建号天王。", process: "1864年湘军合围天京，洪秀全拒李秀成让城别走之议，专信天父、不加兵粮；6月1日（同治三年五月二十七日）殁于城中，年五十一，秘不发丧，城破后其尸被掘而焚戮，并碎其印玺送京师验。", impact: "其死后幼天王旋败，拜上帝会所创之政、教、田制诸法同日而废；然以平等平均之说动天下之端、以神道设教而立国之法，自后之论革命者莫不引之，至1920年代犹以金田为中国社会革命之前驱。", figures: ["洪秀全","洪仁玕","李秀成"], place: "江苏天京（今江苏南京）", state: "清", sources: ["《洪仁玕自述》","《曾国藩全集·奏稿》","罗尔纲《太平天国史》"], tags: ["洪秀全","天王"] }, related: ["cn--1843--p02", "cn--1864--m01"] },
  { id: "cn--1864--c01", track: "cn", year: 1864, yearApprox: false, dim: "culture", weight: 3, title: "《万国公法》译刻行世", summary: "中国始有国际法之书。", detail: { background: "总理衙门与外国交涉日多，恒苦于无案牍之可据，美国传教士丁韪良译惠顿氏《万国公法》已成稿。", process: "1864年丁韪良所译《万国公法》四卷刻成，总理衙门拨银刊印、分发各通商大臣与驻外之员，序称其书足以考国与国交接之理；书中分论邦国自治、相邻、通行、约章、开战、守局之条，以中外已定之约相证。", impact: "此为国际法有中文之始，自后之天津教案、马嘉理案、伊犁改约诸役，中国使臣皆以公法与约章为辨；曾纪泽使俄得改所失之地，论者归功于此曹，而公法于强国弱国果能一视与否，亦自是成为中国士论聚讼之端。", figures: ["丁韪良","奕訢","惠顿"], place: "京师、浙江宁波", state: "清", sources: ["丁韪良译《万国公法》","《（同治）东华录》","《清季中外关系史料》"], tags: ["万国公法","国际法输入"] }, related: ["cn--1861--i01", "cn--1881--p01"] },
  { id: "cn--1864--m02", track: "cn", year: 1864, yearApprox: false, dim: "military", weight: 2, title: "左宗棠克杭州，浙江平", summary: "楚军东下，半岁而两省底定。", detail: { background: "1862年左宗棠由曾国藩荐任浙江巡抚，以楚军数千入浙，地广兵单，专守衢州、宁波之角。", process: "1863年2月楚军会同常捷军与法将德克迪克绍兴，1864年3月31日克杭州，侍王李世贤走江西，左宗棠因是晋闽浙总督；其军饷半取于浙之厘金与洋税，船政之议即成于此时。", impact: "浙江之复使天京失其粮地与出海之口，阅四月而金陵随陷；左宗棠由是自立一军、与曾李鼎足，其后平闽、剿捻、收新疆皆以浙中将领与闽饷为骨干，东南遂成曾左李三家之分局。", figures: ["左宗棠","李世贤","德克迪"], place: "浙江杭州、绍兴", state: "清", sources: ["《左宗棠全集·奏稿》","《（同治）东华录》","马士《中华帝国对外关系史》卷二"], tags: ["杭州","楚军"] }, related: ["cn--1862--m02", "cn--1866--i01"] },
  { id: "cn--1865--i01", track: "cn", year: 1865, yearApprox: false, dim: "institution", weight: 4, title: "创设江南机器制造总局", summary: "中国第一大机器厂兴于沪上。", detail: { background: "苏州、杭州既平，李鸿章以为中国军器之不利远甚于外国，欲自强先须自造，乃议并数局为一。", process: "1865年冬李鸿章署两江总督时奏设江南机器制造总局于上海虹口，合苏州洋枪局与容闳自美国购回之机器为一厂，1867年迁上海县城南高昌庙，扩厂地至七百余亩，费银由江海关洋药厘金与各省协拨支给。", impact: "江南制造局为近代中国第一大厂，先后造轮船二十余艘、枪炮弹药无数，并附设翻译馆、枪厂、船坞；其制以官府拨款、官员经理而不计赢绌，成本倍于外购、工效逊于外厂，论者以为官办工业之病即始于斯，而其器具与译书又实为后来海军与科学之根基。", figures: ["李鸿章","曾国藩","容闳","马格里"], place: "江苏上海（今上海）", state: "清", sources: ["《（同治）东华录》","中国史学会编《洋务运动》","容闳《西学东渐记》"], tags: ["江南制造局","官办工业"] }, related: ["cn--1863--x01", "cn--1868--s01"] },
  { id: "cn--1865--s01", track: "cn", year: 1865, yearApprox: false, dim: "science", weight: 3, title: "徐寿等自造轮船黄鹄号", summary: "中国自造轮船之第一艘。", detail: { background: "安庆内军械所既造蒸汽机模型，曾国藩以为既能造机即可造船，徐寿（1818—1884）、华蘅芳遂移江宁任其事。", process: "1865至1866年间徐寿、华蘅芳造成木壳明轮小火轮一艘，曾国藩与赵烈文试验于江宁下关至三山街之江面，逆流下行而机不停，命名黄鹄，为中国自造轮船之第一艘；其船制未精、不能重载，仅给官用。", impact: "自造轮船之议由是可信，1866年左宗棠遂有福州船政之奏，1868年江南制造局成恬时号；徐寿、华蘅芳后皆入翻译馆，华蘅芳译《代数术》《微积溯源》，徐寿译《化学鉴原》，中国近世工程与化学之命名多出其手。", figures: ["徐寿","华蘅芳","曾国藩","赵烈文"], place: "江苏江宁（今南京）", state: "清", sources: ["赵烈文《能静园日记》","《清史稿·徐寿传》","《曾国藩全集·日记》"], tags: ["黄鹄号","自造轮船"] }, related: ["cn--1861--i02", "cn--1866--i01"] },
  { id: "cn--1865--m01", track: "cn", year: 1865, yearApprox: false, dim: "military", weight: 3, title: "捻军歼僧格林沁于曹州", summary: "马队尽丧，京营无可用之兵。", detail: { background: "1864年太平天国亡后，捻军与太平军余部赖文光、张宗禹合，易步为骑，转走鄂豫山东，避城垒而野战。", process: "1865年5月僧格林沁追捻自山东菏泽至曹州西北之高庄集，连日不得食、马疲人困，为捻所围，5月18夜突围至吴家店战死（一说为捻卒所加），所部马队尽丧，清廷震悼，辍朝设祭。", impact: "京营马队与绿营最后一支主力覆于一村，中央遂无兵可倚，一切委之督抚之军，曾国藩督剿、李鸿章代将，1868年捻事之平全赖淮军与洋枪炮；而黄淮以北自此兵匪相寻，民生日蹙，教案与斋匪之起皆乘其隙。", figures: ["僧格林沁","赖文光","张宗禹"], place: "山东曹州（今菏泽）", state: "清", sources: ["《（同治）东华录》","《钦定剿平捻匪方略》","《清史稿·僧格林沁传》"], tags: ["曹州","捻军"] }, related: ["cn--1855--m02", "cn--1868--m01"] },
  { id: "cn--1865--e01", track: "cn", year: 1865, yearApprox: false, dim: "economy", weight: 2, title: "英商筑铁路宣武门外，毁之", summary: "中国土地始有火车，即日拆去。", detail: { background: "五口既开，洋商以转运利便为请，总理衙门以机车电线为惊众、破风水之器，凡有请皆驳。", process: "1865年英商于京师宣武门外筑短轨一段、驶小小火轮车试验，都人聚观数千，步军统领以惊扰入奏，谕令即时拆毁；英商复议由上海至吴淞兴造铁路，地方官持不可，至1874年乃有擅自筑路之举。", impact: "此为中国土地上出现铁路之始，而以惊众毁弃收场，其后十五年争铁路者皆沿此论；1880年刘铭传请造津沪之路大起廷议，1881年只准先造唐山运煤之路，中国铁路之议比日本明治之创办迟二十年而后进。", figures: ["奕訢"], place: "京师宣武门、上海", state: "清", sources: ["《（同治）东华录》","《翁同龢日记》","《清史稿·奕訢传》"], tags: ["铁路","宣武门"] }, related: ["cn--1881--e01", "cn--1876--e01"] },
  { id: "cn--1866--i01", track: "cn", year: 1866, yearApprox: false, dim: "institution", weight: 3, title: "奏设福州船政于马尾", summary: "造船与教人并立一局。", detail: { background: "安庆、江宁自造轮船既有效，左宗棠以福建之木工、水手与马尾之地利，专任造舰之局。", process: "1866年左宗棠奏于福建闽县之马尾设局造舰，与法商日意格立约：五年成大小轮船十余艘，并教中国匠徒制造驾驶之法，月拨闽海关税银四万两、通年约需四百万两；十二月谕准，左宗棠奉命督师西入，荐在籍之沈葆桢自代。", impact: "马尾船政为东亚最早之近代船厂与海军学校，立前学堂习制造、后学堂习驾驶，兼设艺圃训练匠徒，严复、邓世昌、刘步蟾、萨镇冰之伦皆出其门；至光绪末凡成船数十艘，而经费日绌、匠师屡易，1884年中法马尾一役船政水师几覆，论者归咎于疆臣不和与调度无方。", figures: ["左宗棠","沈葆桢","日意格"], place: "福建福州马尾（今福州）", state: "清", sources: ["《左宗棠全集·奏稿》","《船政奏议汇编》","《（同治）东华录》"], tags: ["船政","海军学校"] }, related: ["cn--1865--s01", "cn--1869--s01"] },
  { id: "cn--1866--x01", track: "cn", year: 1866, yearApprox: false, dim: "explore", weight: 3, title: "斌椿奉派游历欧洲", summary: "中国官员亲至泰西之始。", detail: { background: "总理衙门苦于不知外国情形，奏派随员与同文馆学生从总税务司赫德西游，以省费之便举之。", process: "1866年赫德告归结婚，清廷以四品衔之斌椿与同文馆学生张德彝、凤仪、彦俊及斌椿之子同照随行，历法国、英国、荷兰、比利时、丹麦、瑞典至俄而还，凡四月余，游历十余国；斌椿有《乘槎日记》《海国图咏》进呈，张德彝有《航海述奇》。", impact: "此为中国官员奉派至欧洲游历之始，虽无议约之责而士大夫圈中始有眼见之书；惟朝议以便途遣人为非国体，守旧者诋之，此局至1868年蒲安臣使团而一变，至1875年烟台案后郭嵩焘出使英国，乃有常驻之使。", figures: ["斌椿","赫德","张德彝"], place: "京师至欧洲各国", state: "清", sources: ["斌椿《乘槎日记》","张德彝《航海述奇》","《清季中外关系史料》"], tags: ["斌椿","游历欧洲"] }, related: ["cn--1868--x01", "cn--1876--p01"] },
  { id: "cn--1866--p01", track: "cn", year: 1866, yearApprox: false, dim: "politics", weight: 2, title: "赫德进《局外旁观局中切论》", summary: "外人一论，移洋务之议于督抚。", detail: { background: "总税务司赫德在华司税十余年，见约章之多事与地方之因循，于告归之先为论以进。", process: "1865至1866年赫德撰《局外旁观局中切论》递总理衙门，谓中外之约既立即宜切实奉行，请派使外国、通商路、开矿藏、用西法练兵、渐改取士之制，且言今日因循则后日之累更重；1866年总理衙门以其论与英使阿礼国修约照会一并交各省督抚将军议。", impact: "督抚复奏纷起，曾国藩、李鸿章、左宗棠、马新贻各陈所见，洋务之议自此由京师一二亲贵移至外重之臣，1867年派使之案与1870年代制造、铁路诸案皆成于此时；然中国改政恒以外国之言为动机，论者由是有外铄与自立之辨。", figures: ["赫德","奕訢","阿礼国","李鸿章"], place: "京师（今北京）", state: "清", sources: ["中国史学会编《洋务运动》","《清季中外关系史料》","马士《中华帝国对外关系史》卷二"], tags: ["局外旁观论","洋务廷议"] }, related: ["cn--1861--i01", "cn--1868--p01"] },
  { id: "cn--1867--c01", track: "cn", year: 1867, yearApprox: false, dim: "culture", weight: 3, title: "同文馆增算学馆，廷议大哗", summary: "礼义与机巧之争，正途之人不应。", detail: { background: "1866年冬总理衙门奏请同文馆增设天文算学一馆，兼以科目正途之人投考，延西人教习。", process: "1867年春御史张盛藻先言其不可，大学士倭仁继以立国之道尚礼义不恃机巧之疏力争，谓若以臣下师事西人则礼义之教衰；奕訢诘以朝中果有精于历算可举之人，倭仁无以对，两疏往复，谕旨卒如原议，然而投考者寥寥，正途之应者多引去。", impact: "此为洋务初期关于西学之第一次公开廷议，中学为体西学为用之调停论由是渐成；正途之人不入同文馆，馆中学生多出寒微与旗籍，西学与仕途两不相摄，矿务、铁路、海军诸议此后每以礼义机巧之说相非，其论调一出于此。", figures: ["倭仁","奕訢","张盛藻"], place: "京师（今北京）", state: "清", sources: ["《（同治）东华录》","《清史稿·倭仁传》","丁韪良《花甲忆旧》"], tags: ["同文馆","礼义机巧之争"] }, related: ["cn--1862--i01", "cn--1876--p01"] },
  { id: "cn--1867--m01", track: "cn", year: 1867, yearApprox: false, dim: "military", weight: 2, title: "捻分东西，左宗棠督陕甘", summary: "中原之兵属李，西北之兵属左。", detail: { background: "1866年冬捻军以敌众难聚，分为东西两股，东捻赖文光在鄂豫，西捻张宗禹渡河入山西、再入陕西依回军。", process: "1867年清以左宗棠为钦差大臣督办陕甘军务、曾国藩督办捻军；左宗棠定取道湖北、以炮队车营入关之策，湘淮各军分道并进而绿营不与；是年西捻破同州、逼西安，东捻北走山东之胶州，曾国藩以河防之策不能奏功。", impact: "自是西北之兵任左宗棠、中原之兵任李鸿章，督抚专兵之局成而中枢不复能节制；西捻入陕又使陕回之局愈结不解，左宗棠以且剿且抚收降众为向导，为十年后出关收新疆留一路之兵。", figures: ["左宗棠","张宗禹","李鸿章","曾国藩"], place: "陕西、山西、山东", state: "清", sources: ["《左宗棠全集·奏稿》","《钦定剿平捻匪方略》","《（同治）东华录》"], tags: ["东西捻","督抚专兵"] }, related: ["cn--1865--m01", "cn--1868--m01"] },
  { id: "cn--1867--p01", track: "cn", year: 1867, yearApprox: false, dim: "politics", weight: 3, title: "阿古柏据喀什，建号洪福", summary: "外国自中亚输入一汗国。", detail: { background: "1864年新疆回汉各起，库车、乌鲁木齐、喀喇沙尔相继陷，各城伯克自立、互攻不休，喀什噶尔之求援于浩罕。", process: "1865年中亚浩罕汗国安集延人阿古柏入喀什噶尔，逐本地之思的克而自立，1867年建号洪福汗国，据喀什、叶尔羌、和田，继取乌鲁木齐、吐鲁番，横征重役而以外国之枪炮自固；英属印度与俄国先后来使通商，1869年英遣福赛斯入其帐。", impact: "阿古柏之政凡十一年，中国遂失天山南路之实，英俄各以是国为屏蔽而相猜；左宗棠于1876年北征、1877年南平，其地复归于中国，而新疆建省之议（1884年定）与沿海塞防之争皆起于此一役，西北自此为中国与俄英相值之地。", figures: ["阿古柏","福赛斯","左宗棠"], place: "新疆喀什噶尔（今喀什）", state: "清", sources: ["《（同治）东华录》","《清史稿·左宗棠传》","曾问吾《中国经营西域史》"], tags: ["阿古柏","新疆危机"] }, related: ["cn--1871--m01", "cn--1877--m01"] },
  { id: "cn--1868--m01", track: "cn", year: 1868, yearApprox: false, dim: "military", weight: 3, title: "东西捻军次第荡平", summary: "十六年之捻事，两月而毕。", detail: { background: "曾国藩督剿以河困之策不能得功，1868年春李鸿章代将其军，淮军与洋枪队并力而外国炮船巡河。", process: "1868年1月东捻覆于扬州东北，遵王赖文光被执死之；西捻张宗禹自山西入直隶，扰及易州、蓟州，震动东陵，李鸿章、左宗棠分道追击，围之于运河与徒骇河之间，8月灭于山东茌平铜城，张宗禹投水不明所终。", impact: "捻事自1853年起凡十六年，直隶、山东、河南、湖北被兵最重，户口田亩之损至今论者犹计其多寡；曾国藩以剿捻无功还任江宁，中枢自此益信外重之兵不可废，淮军为天下劲旅，1870年天津教案后更成京师唯一之威。", figures: ["李鸿章","赖文光","张宗禹"], place: "山东茌平、江苏扬州", state: "清", sources: ["《钦定剿平捻匪方略》","《（同治）东华录》","《李鸿章全集·奏稿》"], tags: ["捻军","河防"] }, related: ["cn--1865--m01", "cn--1870--p01"] },
  { id: "cn--1868--s01", track: "cn", year: 1868, yearApprox: false, dim: "science", weight: 3, title: "江南制造局翻译馆开译", summary: "西人口授、华士笔述之定例。", detail: { background: "制造局既成于高昌庙，曾国藩、马新贻相继以为造器不如译书，徐寿、华蘅芳请以馆译任之。", process: "1868年江南机器制造总局设翻译馆于上海高昌庙，聘英人傅兰雅、伟烈亚力与华人之通西文者分任，西人口授而华人笔述，先译化学、机器、矿务、天文、舆地诸书，徐寿译《化学鉴原》以外国首音定元素之名。", impact: "译书之例至此大定，格致、化学、电机、电气、矿石、元素诸名半出于此馆；自1868至清末所译百六十种以上（据其著录书目），为维新之世士大夫学西学之主要文本，康有为、谭嗣同、梁启超皆自言自制造局译书入门，其影响在器用之上。", figures: ["傅兰雅","徐寿","华蘅芳","曾国藩"], place: "上海高昌庙（今上海）", state: "清", sources: ["熊月之《西学东渐与晚清社会》","徐寿译《化学鉴原》凡例","《（同治）东华录》"], tags: ["翻译馆","科技译书"] }, related: ["cn--1859--s01", "cn--1865--i01"] },
  { id: "cn--1868--p02", track: "cn", year: 1868, yearApprox: false, dim: "politics", weight: 2, title: "扬州教案，教堂被焚", summary: "传教与地方相激，一案而动兵船。", detail: { background: "1860年代内地会教士入扬州设讲所，教民不入祠、不输社费，词讼皆仰领事，士绅积不能平。", process: "1868年8月扬州府城教堂与教士寓所被焚，英籍传教士戴乐知家口受伤，抢毁之案起；英使阿礼国向总理衙门抗议，遣兵船入长江，命曾国藩自金陵往查，赔银、惩凶而未得允其严惩之请。", impact: "此为1870年天津教案之先声，中外关于传教与地方之冲突自此岁岁有案；总理衙门以赔款息事而不能止其后，士论则以教民为地方之害、教士为约章之媒，湘籍与清流之士交章论列，教案问题自此与内政、外交并为一事。", figures: ["戴乐知","曾国藩","阿礼国"], place: "江苏扬州（今扬州）", state: "清", sources: ["故宫博物院编《清末教案史料》","《（同治）东华录》","马士《中华帝国对外关系史》卷二"], tags: ["扬州教案","传教冲突"] }, related: ["cn--1864--c01", "cn--1870--p01"] },
  { id: "cn--1868--x01", track: "cn", year: 1868, yearApprox: false, dim: "explore", weight: 2, title: "蒲安臣使团遍历欧美各国", summary: "以外国人为中国之使臣。", detail: { background: "各国请中国派使而总理衙门无可派之人，美使蒲安臣任满将归，自言愿代中国往说各国，奕訢是其议而奏派之。", process: "1868年2月蒲安臣率记名使臣团队出京，以满洲侍讲学士恒祺为副，历美国、英、法、普、俄、丹、荷、比、意、奥十一国，所至以不再增索、惟期和好为辞，1870年10月病殁于圣彼得堡；其团中同文馆学生六人随习翻译。", impact: "此为中国第一次以正式使臣巡说各国，虽以外国人任之而各国待以邦交之礼，总理衙门由此知遣使之可行；1870年后派使之议渐定，1875年因马嘉理案命郭嵩焘使英国，为中国常驻外国之使臣之始，其间论者犹以用夷变夏非之。", figures: ["蒲安臣","恒祺","奕訢"], place: "北京至欧美十一国", state: "清", sources: ["《（同治）东华录》","容闳《西学东渐记》","《清季中外关系史料》"], tags: ["蒲安臣使团","遣使之始"] }, related: ["cn--1868--p01", "cn--1876--p01"] },
  { id: "cn--1868--p01", track: "cn", year: 1868, yearApprox: false, dim: "politics", weight: 3, title: "蒲安臣以美人充中国专使", summary: "中国人第一次自行走遍西洋。", detail: { background: "1867年美国公使蒲安臣任满将归，总理衙门以其与中外相安、又自请为中国往说各国，奏请以使臣之礼派往，开中国遣使之先声。", process: "1868年（同治七年）蒲安臣以「办理中外交涉事务大臣」率团出海，5月在华盛顿与美立《中美续增条约》，许两国人民往来居住各从其便；使团继历英、法、普、荷兰、丹、意、比、西班牙诸国，1870年2月蒲安臣病故于圣彼得堡，其秋使团归天津，前后凡三年。", impact: "《蒲安臣条约》为华工往美之凭，1880年代美国限制、排斥之法即起于此约之隙；此举又以外国人为中国专使走遍各国，使臣与译报渐成衙门之常具，1876年郭嵩焘之驻英、1880年代分使各国皆远承其端，论中国使节制度者必原于此行。", figures: ["蒲安臣","容闳"], place: "美国华盛顿、伦敦、圣彼得堡", state: "清", sources: ["王铁崖编《中外旧约章汇编》第一册","容闳《西学东渐记》","《清季外交史料》"], tags: ["出使外国","蒲安臣条约"] }, related: ["cn--1876--p01", "cn--1882--p01", "cn--1868--x01"] },
  { id: "cn--1869--m01", track: "cn", year: 1869, yearApprox: false, dim: "military", weight: 2, title: "左宗棠入关，董福祥受抚", summary: "以降众为兵，陕东遂定。", detail: { background: "左宗棠定先清关陇而后及河西之策，以炮队攻城、以团队护饷，1869年春督军入潼关。", process: "1869年湘军刘松山一旅克鄠县、盩厔一带回寨，进逼陕甘之交；陕北饥民之从乱者十余万聚董志原，董福祥等乞抚，左宗棠收其壮者编为董字三营，余众给以种牛荒田、安插屯垦，陕东一律肃清。", impact: "以回制回、以降众为兵之法由是通行，董福祥一军后遂为甘军之柱石，1896年与各国之争亦为其人；陕东既定，左宗棠得专力于甘肃与河西，1872年克肃州，1876年即以所部出关收新疆，晚清西北之兵皆基于此。", figures: ["左宗棠","董福祥","刘松山"], place: "陕西潼关、甘肃董志原", state: "清", sources: ["《左宗棠全集·奏稿》","《清史稿·董福祥传》","《（同治）东华录》"], tags: ["陕甘用兵","收抚降众"] }, related: ["cn--1862--m03", "cn--1873--m01"] },
  { id: "cn--1869--s01", track: "cn", year: 1869, yearApprox: false, dim: "science", weight: 2, title: "船政首造轮船万年清成", summary: "千余吨之舰，华匠成之。", detail: { background: "马尾厂屋成、外国机器与匠师至，日意格董其工，先依法国之图造兵轮船。", process: "1869年船政首造木壳轮船成，名万年清，吨位千余吨（各册所载小数略有出入），机器购自外国而船身由华匠与艺徒合成，试航自福州历厦港抵上海；沈葆桢以中国员管驾、匠徒随习为程，并奏定轮船上练水兵之制。", impact: "日意格任内五年成船十五艘、艺徒数千，船政由此兼为工厂与学校；然船身、轮机、图样终不能离外国之料与法，煤费与修费岁巨，1884年中法马尾之役船政所造诸舰不敌其师之炮，论者以自造不能自成其器为一大教训。", figures: ["日意格","沈葆桢"], place: "福建福州马尾（今福州）", state: "清", sources: ["《船政奏议汇编》","《清史稿·沈葆桢传》","《（同治）东华录》"], tags: ["万年清","自造兵轮"] }, related: ["cn--1866--i01", "cn--1884--m01"] },
  { id: "cn--1870--p01", track: "cn", year: 1870, yearApprox: false, dim: "politics", weight: 4, title: "天津教案，教堂被焚", summary: "外命二十，一案而启天下之议。", detail: { background: "法国天主教堂在天津设仁慈堂育婴，时疫之年婴孩多殁，拐孩取心之谣遍传，教民倚领事抗官，积年相猜。", process: "1870年6月21日天津民众围仁慈堂与望海楼教堂，法国领事及神父、修女、商民并被杀者二十人，华民之从教者死数十，教堂与育婴堂同毁；总理衙门命曾国藩往查，旋由李鸿章接办，结案骈首者十余人、流遣者数十人、赔恤银四十余万两（刑部档与法档、近人考订之数略有出入），又以派使谢罪为约外之请。", impact: "天津教案为同治、光绪间教案之最巨者，自此教案岁有而中外各持一说：外国以护教责中国而不能禁其民入内地，士大夫以教民为地方之害而莫能去；清廷以惩民谢外为办案常格，舆论由是大失望于政府，郭嵩焘之被讥、庚子之拳匪皆伏笔于此案。", figures: ["曾国藩","李鸿章","崇厚"], place: "直隶天津（今天津）", state: "清", sources: ["故宫博物院编《清末教案史料》","《清季外交史料》","马士《中华帝国对外关系史》卷二"], tags: ["天津教案","民教相仇"] }, related: ["cn--1868--p02", "cn--1870--p02"] },
  { id: "cn--1870--p02", track: "cn", year: 1870, yearApprox: false, dim: "politics", weight: 2, title: "崇厚奉使法国谢罪", summary: "中国派专使西洋之始。", detail: { background: "天津教案之结，法以惩凶、赔款之外更索遣使往谢，朝议以《万国公法》有遣使之文而礼家无其礼，迟回两载。", process: "1870年命协办大学士、户部尚书崇厚为钦差大臣出使法国，1871年春抵欧时法方内乱未已，乃就凡尔赛呈递国书而返；随行有官弁学生数人，沿途考其船政、炮台与制造。", impact: "此举于礼制为破天荒，廷议哗然者数年，谓以天子之卿谢罪于外邦为非体；而中国由此知使臣可以常驻，1875年后分驻伦敦、巴黎、柏林、华盛顿之使节相继，礼部、理藩院主涉外之旧局终于让位，公法与使礼之书自此为衙门之常课。", figures: ["崇厚","奕訢"], place: "直隶天津至法国巴黎", state: "清", sources: ["《清季外交史料》","《（同治）东华录》","《翁同龢日记》"], tags: ["遣使","天津教案"] }, related: ["cn--1870--p01", "cn--1876--p01"] },
  { id: "cn--1870--i01", track: "cn", year: 1870, yearApprox: false, dim: "institution", weight: 3, title: "幼童出洋肄业之议得允", summary: "官派留学之案定于津案之后。", detail: { background: "容闳自1863年即陈派遣游学之策，丁日昌、曾国藩先后是其议，适天津教案之后乘势上请。", process: "1870年曾国藩、李鸿章会奏派幼童赴美国肄业，定每批三十人、合四批为一百二十人，年在十二至十六之间，期以九年，派陈兰彬为正委员、容闳为副，设局于上海招收，经费由江海关道按年筹拨；1871年所定章程十六条成。", impact: "此为中国官派留学之始，自后电报、铁路、矿务、海军、外交诸业之人才多出其中，然以中学为率、西学为辅之约始终不能两全，1881年全数撤回之案即由此起，为近代留学事业第一大折。", figures: ["曾国藩","容闳","陈兰彬","李鸿章"], place: "京师、上海", state: "清", sources: ["《曾国藩全集·奏稿》","容闳《西学东渐记》","舒新城《中国留学教育史》"], tags: ["留学","官派学生"] }, related: ["cn--1863--x01", "cn--1872--x01"] },
  { id: "cn--1871--m01", track: "cn", year: 1871, yearApprox: false, dim: "military", weight: 4, title: "俄国出兵占伊犁", summary: "乘乱踰界，十年不还。", detail: { background: "1864年以后新疆各城相继乱起，伊犁惠远城为回众所据，通商之俄商与俄属之人被劫，俄方以保护商务为名蓄谋久。", process: "1871年5月俄国自维尔内派兵踰界，五月下旬据伊犁惠远诸城，声言回乱平定即行交还；清廷方用兵甘肃，仅命乌里雅苏台将军荣全前往查询，荣全至塔城而不能进，驻疆之兵无一出关者，伊犁遂入俄人之守。", impact: "俄占伊犁凡十年，1879年崇厚所定之约因割地过多加赔款而京帅交章请改，1881年曾纪泽改约仅得回特克斯一带，兵费反增；中国由是确知新疆不可弃，1875年定议出师、1884年建行省，西北与海防之辨与东北疆局皆自伊犁一事定其规模。", figures: ["荣全","左宗棠"], place: "新疆伊犁（今伊宁）", state: "清", sources: ["《（同治）东华录》","《清史稿·左宗棠传》","《清季外交史料》"], tags: ["伊犁","俄占"] }, related: ["cn--1867--p01", "cn--1881--p01"] },
  { id: "cn--1871--p01", track: "cn", year: 1871, yearApprox: false, dim: "politics", weight: 3, title: "中日《修好条规》立于天津", summary: "与东邻始为对等之约。", detail: { background: "日本明治维新后屡遣使请立约，总理衙门欲防其窥台湾而牵制朝鲜，乃以西洋成例之形而删其最惠、内地两款。", process: "1871年7月中日《修好条规》与《通商章程》订于天津，直隶总督李鸿章与日本大藏卿伊达宗城任之：两国派使常驻、罪犯各归本国查办、口岸相准通商而不许入内地，约文对等而无一体均沾之条，是为日本与中国以近代条约相接之始。", impact: "论者以李鸿章于此约独能去西洋成例之为害，然日本终不满足：1873年副岛种臣入觐而勘朝鲜、台湾之虚实，1874年即因台湾漂人之案发兵，中国以两字对等之约不能约束东邻之兵，甲午之祸其端已在是约十年之后。", figures: ["李鸿章","伊达宗城"], place: "直隶天津（今天津）", state: "清", sources: ["王铁崖编《中外旧约章汇编》第一册","《清季外交史料》","《（同治）东华录》"], tags: ["中日条约","对等之约"] }, related: ["cn--1873--p02", "cn--1874--m01"] },
  { id: "cn--1872--x01", track: "cn", year: 1872, yearApprox: false, dim: "explore", weight: 3, title: "第一批幼童赴美肄业", summary: "十二岁之客，万里之行。", detail: { background: "留学章程既定，上海设局招收而应者寥寥，惟广东香山县一带人家肯送子弟远适。", process: "1872年8月第一批幼童三十人自上海乘船抵旧金山，旋分驻美国人家入学，正委员陈兰彬、副委员容闳领之；1873、1874、1875年三批继行，合四批凡一百二十人，年在十二至十六之间，期以九年，经费岁由江海关道拨解。", impact: "幼童既入美国学堂，渐习嬉戏、奉基督之教而疏四书，1881年吴子登诸人以是请尽撤，全数回华，肆业至高校卒业者仅詹天佑、欧阳庚二人；其后京张铁路、电报、矿务、外交诸局多出此百二十人之手，而中途撤回之失至今论留学者引以为戒。", figures: ["容闳","陈兰彬","詹天佑"], place: "上海至美国旧金山", state: "清", sources: ["容闳《西学东渐记》","《（同治）东华录》","舒新城《中国留学教育史》"], tags: ["幼童留美","留学教育"] }, related: ["cn--1870--i01", "cn--1909--i01"] },
  { id: "cn--1872--m01", track: "cn", year: 1872, yearApprox: false, dim: "military", weight: 3, title: "大理城陷，杜文秀死", summary: "十七年之滇事毕于一城。", detail: { background: "岑毓英复昆明、迤东诸城之后，清军三道而西攻大理，炮击外郛，城中食且尽。", process: "1856至1872年杜文秀据大理，立幕府、用汉回参佐、通商旅以自固；1872年11月杨玉科军穴地破城，杜文秀服毒后出降被杀（一说服毒未死而就刑），城内外被杀者数万，清方奏报与近人考订之数多寡互异；1873年马德新亦遇害于新兴，迤西一律平。", impact: "云南回事前后十七年，全省户口、田亩、矿业大损，汉回相猜延及百年而不能解；岑毓英、唐炯由是任滇事，以抚回、垦荒、理财为务，而腾越、顺宁之矿与西南边防亦因此不能复，1894年中英定滇界与1897年之铁路权利皆乘其敝。", figures: ["杜文秀","岑毓英","杨玉科"], place: "云南大理（今大理）", state: "清", sources: ["中国史学会编《回民起义》","《清史稿·岑毓英传》","《（光绪）云南通志》"], tags: ["大理","杜文秀"] }, related: ["cn--1856--m04", "cn--1875--p01"] },
  { id: "cn--1872--e01", track: "cn", year: 1872, yearApprox: false, dim: "economy", weight: 4, title: "创设轮船招商局", summary: "官督商办之第一公司。", detail: { background: "1860年代外国轮船并夺长江与沿海之运，沙船之业大困，上海绅商朱其昂、唐廷枢等请以华商自组航运。", process: "1872年冬李鸿章奏设轮船招商公局于上海，定官督商办之制：招商集股而借公款为其先，漕粮改由局船承运以为稳固之利，置轮航行天津、上海、牛庄之线；1873年正式开局营业，唐廷枢、徐润继朱其昂主其事。", impact: "此为中国第一家官督商办之公司，1877年购并美国旗昌洋行之产业而并有其码头与船只，长江与沿海之运始有华籍之敌手；而其制以官为主而商任其股，盈余归公、商股无议政权，任人由于衙门，论者以晚清公司制度之病根实始于斯。", figures: ["李鸿章","唐廷枢","朱其昂","徐润"], place: "江苏上海（今上海）", state: "清", sources: ["《（同治）东华录》","中国史学会编《洋务运动》","《海关十年报告》近代史所译本"], tags: ["轮船招商局","官督商办"] }, related: ["cn--1865--i01", "cn--1880--e01"] },
  { id: "cn--1872--f01", track: "cn", year: 1872, yearApprox: false, dim: "figure", weight: 1, title: "曾国藩卒于江宁督署", summary: "湘军之立起者，以一身收其局。", detail: { background: "曾国藩（1811—1872）湖南湘乡人，自在籍办团练起家，官至两江总督、直隶总督，封一等毅勇侯。", process: "1868年调任直隶、1870年因天津教案再回两江，处中外之冲，名誉大损；1872年8月4日（同治十一年六月初六）卒于江宁督署，年六十二，谥文正，遗疏以不积银、不作官为家戒，生平日记、家书、奏稿手札皆为后世史家之要籍。", impact: "身后湘军之饷与淮军之兵并起，而湘系渐微，曾国荃旋以劾归里；其以礼教自任、兼营刻书与译书之风，开曾左李刘数代疆臣之格局，论清代末年理学与经世之合流者必归于曾国藩，其幕府所养人才并为一代吏治之源。", figures: ["曾国藩","李鸿章","曾国荃"], place: "江苏江宁（今南京）", state: "清", sources: ["《曾国藩全集·奏稿》","黎庶昌《曾文正公年谱》","王闿运《湘军志》"], tags: ["曾国藩","湘军"] }, related: ["cn--1853--f01", "cn--1864--m01"] },
  { id: "cn--1872--c01", track: "cn", year: 1872, yearApprox: false, dim: "culture", weight: 3, title: "《申报》创刊于上海", summary: "中文日报之历时最久者。", detail: { background: "开埠后上海之西文报馆已十余家，华人通市者渐需新闻与市价之报。", process: "1872年4月30日英商美查等集资在上海创刊《申报》，纯用华文，日出一大张，以商情、船期、刑名、琐闻相杂，延华人主笔；其后用价低廉、广告广收之法，岁有盈余，1909年售归华人席氏，1912年为史量才接办，至1949年7月停刊，凡七十七年。", impact: "《申报》为近代中国历时最久之中文日报，其广告与副刊养成近代市民之读报习惯，报刊之论议渐成舆论之门；1903年《苏报》案起而言路与报禁相激，报馆与官府、商民三方之势由是渐成，论中国近世公共舆论者每以《申报》为据。", figures: ["美查","史量才"], place: "江苏上海（今上海）", state: "清", sources: ["《申报》原刊","《（光绪）东华录》","戈公振《中国报学史》"], tags: ["申报","近代报刊"] }, related: ["cn--1843--e01", "cn--1884--c01"] },
  { id: "cn--1873--m01", track: "cn", year: 1873, yearApprox: false, dim: "military", weight: 3, title: "克肃州，陕甘事平", summary: "河西既定，始议出关。", detail: { background: "1871年刘松山战死于金积堡之下，其侄刘锦棠代将其军，左宗棠以炮队攻城、以车营护饷道，河西回军各据城堡。", process: "1872年徐学功等军进拔河西各堡，1873年9月刘锦棠军炮击肃州城破，白彦虎走新疆旋入俄境，河州、西宁之众先后来降；陕甘用兵自1862年至此凡十一年而毕。", impact: "左宗棠军饷半仰各省协拨与洋款，因是创甘局、陕局之制而饷权日重；善后以清田亩、兴蚕桑、设义学、建城池为务，回汉分隔之局则未能改，同治之创痍至光绪乙亥河湟复起（1895年）犹未平，西北回汉之讼为晚清边政最难事。", figures: ["左宗棠","刘锦棠","白彦虎"], place: "甘肃肃州（今酒泉）", state: "清", sources: ["《左宗棠全集·奏稿》","《（同治）东华录》","《清史稿·左宗棠传》"], tags: ["肃州","陕甘善后"] }, related: ["cn--1869--m01", "cn--1877--m01"] },
  { id: "cn--1873--p01", track: "cn", year: 1873, yearApprox: false, dim: "politics", weight: 2, title: "穆宗亲政与议修圆明园之罢", summary: "归政之名，垂帘之实。", detail: { background: "穆宗年十八，两宫于本年正月撤帘归政，而用人行政仍咨承懿旨，恭亲王与军机处之势微。", process: "1873年九月以内廷指用不敷为词议重修圆明园，恭亲王奕訢、李鸿藻与户部诸臣以库绌力争，曾国藩上疏言不宜以土木夺海防之饷，两宫寻谕只行葺海淀数处而卒不果；同月因大婚、亲政之典，中外使臣觐见之礼又起争执。", impact: "亲政之名与垂帘之实并行，恭亲王由是渐失西太后之信、光绪朝遂退处不预枢要，中枢无可为中外主持之人；修园之案显见户部之空与内用之无节，其后海军经费与颐和园工程相引为论者，实张本于此一年。", figures: ["奕訢","曾国藩","李鸿藻"], place: "京师（今北京）", state: "清", sources: ["《（同治）东华录》","《清史稿·恭亲王奕訢传》","《翁同龢日记》"], tags: ["亲政","圆明园之议"] }, related: ["cn--1861--p01", "cn--1885--i01"] },
  { id: "cn--1873--p02", track: "cn", year: 1873, yearApprox: false, dim: "politics", weight: 2, title: "日本使臣入觐，朝鲜台湾之问", summary: "一答之轻，启两事之端。", detail: { background: "日本既立天津之约，1873年以外务卿副岛种臣为钦差大臣，借换约并贺亲政入京觐见。", process: "1873年6月副岛种臣至天津、入北京，其随员先以照会询台湾生番之杀琉球漂人者与朝鲜之属于中国与否，总理衙门答以台湾生番早归王化而其杀人为可罪、朝鲜自为一国而藩礼不废，其内治不必预；觐见之礼以五鞠躬成。", impact: "日本由是判定台湾之番地与朝鲜皆可以兵加而无损于中国之名分，1874年琅峤之师、1876年江华岛之约相继而起，属国之系自此渐解；总署一答之轻为近代外交一大失算，论者归咎于洋务诸臣于公法上属国之义本无定说，而译报之不通夷情尤甚。", figures: ["副岛种臣","奕訢","李鸿章"], place: "直隶天津、京师", state: "清", sources: ["《清季外交史料》","《（同治）东华录》","《清史稿·邦交志》"], tags: ["属国之制","日本窥台"] }, related: ["cn--1871--p01", "cn--1874--m01"] },
  { id: "cn--1874--m01", track: "cn", year: 1874, yearApprox: false, dim: "military", weight: 4, title: "日本兵侵台湾，台事专条成", summary: "生番一案，偿银五十万两。", detail: { background: "1871年八重山琉球漂人五十余至台湾南部，为琅峤八瑶社生番所杀，日本以琉球我属、中国不办为辞议用兵。", process: "1874年5月日本以中将西乡从道率兵三千余自琅峤登岸攻番社，疫死者六百余人；清廷命福州船政大臣沈葆桢为钦差大臣赴台视师，增兵渡台、开北路之番地而不与之战；10月北京订《台事专条》三款，日本撤兵，中国给银五十万两（其中恤赏与收买其房舍道路之费），并认其之举为保民。", impact: "中国以五十万两与一句认其保民之辞了结台事，日本遂以琉球为已有成竹，1879年竟改琉球为冲绳县而不能争；清廷自此始悟台、澎之不可忽，沈葆桢开山抚番、设电线、建炮台，至1885年台湾建省，皆缘此案而起，而东海之局自此一变。", figures: ["西乡从道","沈葆桢","李鸿章","大久保利通"], place: "台湾琅峤（今恒春）、京师", state: "清", sources: ["王铁崖编《中外旧约章汇编》第一册","《清季外交史料》","刘锦藻《清续文献通考》"], tags: ["日本侵台","台事专条"] }, related: ["cn--1873--p02", "cn--1879--p01"] },
  { id: "cn--1874--p01", track: "cn", year: 1874, yearApprox: false, dim: "politics", weight: 4, title: "穆宗崩，载湉入承大统", summary: "以弟后兄，同光之局定于一夕。", detail: { background: "1873年亲政之后，宫府之意不能相下，帝崩于大婚之后未及一年，年十九。", process: "1874年12月穆宗崩于养心殿东暖阁，太医所诊为天花，脉案今存中国第一历史档案馆（近人亦有别推者）；慈禧太后与奕訢等定议，不取溥字辈近支而迎醇亲王奕譞之子载湉入承文宗为子、继穆宗之统，年四岁，两宫太后再次训政，皇后阿鲁特氏以忧殂。", impact: "以弟继兄、统嗣淆而母子之名不正，故光绪无嗣而立溥俊为大阿哥、宣统之立与退位皆缘此局；太后再垂帘垂三十四年，内廷与政府之势常离，清流与洋务之争以宫府为归，朝局无一可久之主，论者以为庚子、辛丑之祸其根本在此一夜之议。", figures: ["那拉氏","奕訢","奕譞","载湉"], place: "京师（今北京）", state: "清", sources: ["《（光绪）东华录》","《清史稿·穆宗本纪》","中国第一历史档案馆藏脉案"], tags: ["同治之死","光绪立"] }, related: ["cn--1873--p01", "cn--1889--p01"] },
  { id: "cn--1875--p01", track: "cn", year: 1875, yearApprox: false, dim: "politics", weight: 3, title: "马嘉理案起于蛮允", summary: "一命之案，换四口与入藏之约。", detail: { background: "英国欲由缅甸通云南之路，1874年先派校官自印度入西藏探路，另派翻译官马嘉理自缅甸北上为期会。", process: "1875年2月马嘉理一行自八莫北行至云南腾越厅属之蛮允，为地方之人所杀，从者多遇害；英使威妥玛据《天津条约》游历之款力争，请派大员查办并以绝交相胁，总理衙门派李鸿章与之力辩于登州烟台。", impact: "滇案之结成《烟台条约》：恤款、惩凶、派使赴伦敦道歉之外，又准英员由川、甘入藏察看大路、增开宜昌芜湖温州北海四口、免洋货入内地之厘；中国以一命之案易数口之地与入藏之名分，论者以为滇案直接启英国窥西藏之路。", figures: ["马嘉理","威妥玛","李鸿章","岑毓英"], place: "云南腾越厅蛮允（今腾冲）", state: "清", sources: ["《清季外交史料》","王铁崖编《中外旧约章汇编》第一册","马士《中华帝国对外关系史》卷二"], tags: ["滇案","入藏探路"] }, related: ["cn--1876--p02", "cn--1876--p01"] },
  { id: "cn--1875--p02", track: "cn", year: 1875, yearApprox: false, dim: "politics", weight: 4, title: "海防塞防之议定策", summary: "一念之间，东南与西北并计。", detail: { background: "1874年日本以台事索银、海防之疏大起，户部以饷绌请停西北各军以实海防，陕甘用兵与新疆未复之局几为之解。", process: "1874至1875年（同治末、光绪初）内外筹议海防，李鸿章主暂撤塞防、移其饷以治海防，左宗棠上疏争之，谓天山一旦不守则蒙部摇动、心腹之病重于肢体；1875年春谕以海防塞防并重，以左宗棠为钦差大臣督办新疆军务，饷项取各省协拨与洋债并行。", impact: "此议定而后新疆之役得有饷源，1876至1878年复天山南北路，1884年遂有建省之诏，中国西北之版图以全；同时海防之备亦因之而兴，南北洋购舰设厂、1885年立海军衙门，皆循此局，论者以同治末之筹议为光绪朝军事财政之枢机。", figures: ["左宗棠","李鸿章","文祥"], place: "京师、直隶、甘肃", state: "清", sources: ["《左宗棠全集·奏稿》","中国史学会编《洋务运动》","《（光绪）东华录》"], tags: ["海防塞防","新疆督办"] }, related: ["cn--1877--m01", "cn--1885--i02"] },
  { id: "cn--1876--p01", track: "cn", year: 1876, yearApprox: false, dim: "politics", weight: 3, title: "郭嵩焘充出使英国大臣", summary: "常驻外邦之使自此有人。", detail: { background: "滇案结而遣使道歉为约中之款，朝士莫肯应命，前在曾国藩幕中、曾驻法京之翰林郭嵩焘（1818—1891）独以自请。", process: "1876年10月郭嵩焘抵伦敦任出使英国大臣，1877年兼驻法国；其在英考求议政、书院、制造、电报诸政，逐日日记所见，刻《使西纪程》于长沙以进，言西洋政教自有本末，不徒在船炮之间；副使刘锡鸿与不能相下，屡疏相攻。", impact: "此为中国常驻外国使臣之始，其后分使各国渐为定制，使署与译报成外交之常具；而《使西纪程》一书大触士论，湖南同乡几欲毁其里居之牌，言官交章劾其张外夷之气，自后论洋务者讳言外国之治本，论者以中国之难得知外，于郭嵩焘之遇见之。", figures: ["郭嵩焘","刘锡鸿","李鸿章"], place: "伦敦、长沙", state: "清", sources: ["郭嵩焘《使西纪程》","《郭嵩焘日记》","《清史稿·郭嵩焘传》"], tags: ["出使大臣","使西纪程"] }, related: ["cn--1870--p02", "cn--1875--p01"] },
  { id: "cn--1876--p02", track: "cn", year: 1876, yearApprox: false, dim: "politics", weight: 4, title: "中英《烟台条约》订于芝罘", summary: "三端之约，江与藏俱开。", detail: { background: "威妥玛以滇案不肯赴京，驻烟台候议，撤使归国相胁，英舰游弋辽海，朝命李鸿章为全权与议。", process: "1876年9月中英《烟台条约》成，凡三端：关于滇案者恤银二十万两、派使谢罪、惩办各员；关于通商税务者增开宜昌、芜湖、温州、北海四口、准华民入各口游历、免洋货入内地之厘而加收洋药之税；另准英员由四川、甘肃赴藏察看大路。", impact: "四口之开使外力沿江上及宜昌、北及北海，英人由此得入藏探路之名分，1880至1890年代请入藏、划滇界诸案皆据此约；条约通商一端又为1902年《马凯商约》之张本，论者以为滇案一命而易数口之地、入藏之路，为咸丰以后最不与偿之交涉。", figures: ["李鸿章","威妥玛"], place: "山东登州芝罘（今烟台）", state: "清", sources: ["王铁崖编《中外旧约章汇编》第一册","《清季外交史料》","马士《中华帝国对外关系史》卷二"], tags: ["烟台条约","四口"] }, related: ["cn--1875--p01", "cn--1886--p01"] },
  { id: "cn--1876--e01", track: "cn", year: 1876, yearApprox: false, dim: "economy", weight: 3, title: "英商筑淞沪铁路，赎而拆之", summary: "以重金买路而自毁其轨。", detail: { background: "1874年英商怡和借运货之名，在沪东筑自县城至吴淞之路，地方官以铁路为碍而阻之不及。", process: "1876年淞沪铁路全线告成行车，华人争乘而司事者骄，6月有华兵被碾毙命之案，上海道与南洋大臣沈葆桢以惊众扰民为请；交涉累月，至1877年以银二十八万五千两赎买全路，旋拆其轨、去其料，议移台湾而未果。", impact: "中国以重金自赎其路而毁之，于守旧者为一快，而外国由此知铁路交涉之可居奇；十年后津沽、唐胥之路相继而筑，1890年代铁路之权与借款相因而尽入各国之手，论者以为吴淞一拆使中国自主筑路之机坐失十年。", figures: ["沈葆桢","怡和洋行"], place: "江苏上海、吴淞（今上海）", state: "清", sources: ["《（光绪）东华录》","《申报》论铁路诸文","金士宣《中国铁路发展史》"], tags: ["淞沪铁路","筑路之禁"] }, related: ["cn--1865--e01", "cn--1881--e01"] },
  { id: "cn--1877--m01", track: "cn", year: 1877, yearApprox: false, dim: "military", weight: 3, title: "湘军北征，复乌鲁木齐", summary: "逾天山而收北路。", detail: { background: "1875年清以左宗棠为钦差大臣督办新疆军务，议定塞防不可废，饷项取各省协拨与洋债，前后借数逾千万两（户部档与近人统计多寡不一）。", process: "1876年8至9月刘锦棠、金顺自北路由巴里坤进，克古牧地、乌鲁木齐、玛纳斯诸城；1877年春湘军逾天山克达坂城、吐鲁番，阿古柏走死（自戕、病殁、为下所戕三说不同），其子内争，南八城之门洞开。", impact: "清军以两年复天山北路，其粮饷军火半出于东南之财与外国之借，此局为外重之制在边防之验；塞防既胜于海防之议，1884年遂有新疆建省之诏，中国西北之版图以全，俄人亦遂无辞可守伊犁，曾纪泽之改约即以是役为后援。", figures: ["左宗棠","刘锦棠","金顺","阿古柏"], place: "新疆乌鲁木齐、达坂城", state: "清", sources: ["《左宗棠全集·奏稿》","《（光绪）东华录》","曾问吾《中国经营西域史》"], tags: ["新疆北征","达坂城"] }, related: ["cn--1867--p01", "cn--1878--m01"] },
  { id: "cn--1877--e01", track: "cn", year: 1877, yearApprox: false, dim: "economy", weight: 3, title: "招商局购并旗昌轮船", summary: "华人公司初收外国之产业。", detail: { background: "轮船招商局初立，与英之太古、怡和及美之旗昌并争沿海、长江之载，各家减价相困，旗昌股东倦于支绌。", process: "1877年春唐廷枢、徐润主持以二百二十二万两购美国旗昌洋行之轮船十艘并上海、汉口各处码头仓库，招商局并旧有凡船二十余艘，购价之半出于借本，由局中以年息偿之，而码头过长、经费过重之病即起于此役。", impact: "此为华人商业第一次收买外国公司之产业，中外之论为之一快；然借本过重、岁息支吾，局中盈余尽为债息所夺，议者遂谓官督商办终不能与公司相敌；英商太古、怡和继与订齐价合同以分航线，中国轮运之权卒不能自主。", figures: ["唐廷枢","徐润","李鸿章"], place: "江苏上海（今上海）", state: "清", sources: ["《（光绪）东华录》","中国史学会编《洋务运动》","《海关十年报告》近代史所译本"], tags: ["旗昌","招商局"] }, related: ["cn--1872--e01", "cn--1885--e01"] },
  { id: "cn--1878--m01", track: "cn", year: 1878, yearApprox: false, dim: "military", weight: 3, title: "克喀什噶尔，全疆底定", summary: "两年之间，南八城尽复。", detail: { background: "阿古柏死而后其子与伯克互争，刘锦棠分道而南，以炮队攻城、以抚降为助。", process: "1877年冬清军取达坂、吐鲁番，1878年1月克喀什噶尔、叶尔羌、英吉沙尔、和阗，白彦虎余众入俄境，除伊犁外全疆底定；是役自1876年出师至是凡两年余，费银至数千万两（户部结算与近人统计多寡不齐）。", impact: "新疆复入版图，1884年遂有建省之诏，伯克世袭与军府之制渐改为行省州县，屯垦赋税与内地相若；然善后之吏不能尽其才，回部之贫与英俄之相伺并存，1882至1884年勘界诸约与1890年代帕米尔之失皆其余波。", figures: ["刘锦棠","左宗棠"], place: "新疆喀什噶尔（今喀什）", state: "清", sources: ["《左宗棠全集·奏稿》","《清史稿·刘锦棠传》","《（光绪）东华录》"], tags: ["南八城","新疆建省"] }, related: ["cn--1877--m01", "cn--1884--i01"] },
  { id: "cn--1878--d01", track: "cn", year: 1878, yearApprox: false, dim: "disaster", weight: 5, title: "丁戊奇荒：华北连年大祲", summary: "五省之旱，人相食者三年。", detail: { background: "1876至1878年（光绪二年至四年，其间丁丑、戊寅两年最酷）华北雨泽全乖，山西、直隶、河南、山东、陕西赤地千里，适值军事初平、仓储未复。", process: "1877、1878两年饥馑最重，粮价腾贵数倍，剥树皮、掘观音土而死者相属，史册累书人相食；晋抚鲍源深、豫抚涂宗瀛等交章告灾，朝命拨漕拨银、准借洋款，李鸿章、曾国荃在直晋办赈，绅商之捐输与《申报》之募助并行，然官吏侵冒、米商闭籴之弊百出，1878年疫疠随饥而起。", impact: "饥民死亡之数诸家所计悬殊，自九百万至一千三百万人不等（近人据户籍、赈报与地方志推算），官方奏报之数字每不及其实；此役使晋商财力大耗、直隶之民流徙关东，曾李诸臣以办赈名其局，其后1889年黄河之灾、1920年西北之荒同受其议，论晚清荒政者每以丁戊为鉴。", figures: ["左宗棠","李鸿章","曾国荃","鲍源深"], place: "山西、直隶、河南、山东、陕西", state: "清", sources: ["《（光绪）东华录》","《申报》赈务诸记载","近人《中国人口史》第五卷"], tags: ["丁戊奇荒","晚清荒政"] }, related: ["cn--1877--m01", "cn--1883--e01"] },
  { id: "cn--1879--p01", track: "cn", year: 1879, yearApprox: false, dim: "politics", weight: 3, title: "日本废琉球为冲绳县", summary: "一藩既灭，属国之藩尽去。", detail: { background: "琉球两属之局由来旧矣，1872年日本封其王为藩王、1875年逼用日本年号而止其受封于中国之礼。", process: "1879年3月日本内务卿松田道之至那霸，废琉球藩为冲绳县，执其王尚泰以归，迁其宗庙祭器；中国驻日公使何如璋与参赞黄遵宪力争，总理衙门复延美前总统格兰特居间，日人议以宫古、八重山诸岛属清而换内地的通商之利，清未之许，案遂搁。", impact: "琉球一亡，中国东南之屏尽去而属国之制始摇，论者归咎于1874年台案认其保民之辞与伊犁方急不能东顾；1882、1884年朝鲜之变、1885年越南之弃相踵而至，十余年间属国之系解尽，甲午之战即为此局之结。", figures: ["何如璋","黄遵宪","尚泰","松田道之"], place: "琉球那霸（今日本冲绳）", state: "清", sources: ["《清季外交史料》","黄遵宪《日本国志》","《（光绪）东华录》"], tags: ["琉球亡","属国之制"] }, related: ["cn--1874--m01", "cn--1882--m01"] },
  { id: "cn--1879--p02", track: "cn", year: 1879, yearApprox: false, dim: "politics", weight: 3, title: "崇厚擅订里瓦底亚之约", summary: "使臣失训电，约成而言路哗。", detail: { background: "伊犁之议自1879年春起，崇厚以全权大臣驻俄，所奉训条限于交还伊城而界务商务可稍让。", process: "1879年10月崇厚在克里米亚之里瓦底亚与俄立《交收伊犁条约》十八款：俄只还伊犁之城与其南之地，而西界大有所削，偿兵费五百万卢布，准俄商由蒙古、新疆至甘肃、北京一带通商免税，并添陆路通商至天津、汉口；奏入，朝廷以不遵训电擅自画押交刑部治罪。", impact: "言官交章请诛崇厚而罢新约，英法各以公法居间，中外几启兵端，左宗棠以湘军四路出关为之声援；1881年改约虽多得特克斯、昭苏一带之地而兵费增至四百五十万卢布，论者于是分为两说，一谓清议误国并失其可以自立之地，一谓使臣不习公法图说之所致。", figures: ["崇厚","曾纪泽","左宗棠"], place: "俄国里瓦底亚、京师", state: "清", sources: ["王铁崖编《中外旧约章汇编》第一册","《清史稿·崇厚传》","《清季外交史料》"], tags: ["伊犁交涉","使臣画押"] }, related: ["cn--1871--m01", "cn--1881--p01"] },
  { id: "cn--1880--e01", track: "cn", year: 1880, yearApprox: false, dim: "economy", weight: 3, title: "创设电报总局于天津", summary: "军机文报，数日者易为片刻。", detail: { background: "外国公司先在上海设海线通香港、大沽，中国官报犹恃驿站，督抚与中枢之文恒迟。", process: "1880年李鸿章奏设电报总局于天津，以盛宣怀总其事，先通大沽、北塘与京师之线；1881年津沪干路成，自天津经济宁、清江浦至上海三千余里，商报收费以抵官线之费，旋设分局于各省。", impact: "电报之制使军机文报与商市行情同时而至，督抚得自主其奏报之速而京外之隔遂破；其后各省继设，至1880年代末官商报线遍于腹地，与外国海线相持，电政成为税厘之外洋务财政之一柱，而线价、报费与用人之权亦累年为中外之争。", figures: ["李鸿章","盛宣怀"], place: "直隶天津至江苏上海", state: "清", sources: ["《（光绪）东华录》","中国史学会编《洋务运动》","《申报》论电报诸文"], tags: ["电报","通信新政"] }, related: ["cn--1872--e01", "cn--1881--e01"] },
  { id: "cn--1880--e02", track: "cn", year: 1880, yearApprox: false, dim: "economy", weight: 2, title: "兰州机器织呢局告成", summary: "西北第一架织呢机器。", detail: { background: "左宗棠平定陕甘后，以本地羊毛弃而不用、呢料反仰外洋，乃于1878年在兰州筹设织布局，募英国机器、雇工匠东来。", process: "1880年前后兰州机器织呢局告成，凡织机百余架（说部所载多寡不一），用水力转动，岁出细呢数千匹；因甘省燃料贵、工费重、土人不好呢货，所织不销，未数年而停闭（一说1883年前后即废）。", impact: "此局为中国以机器制毛料之始，虽以亏折告终，然其用人、用水与转轮之法自西北土著见之；议者以为洋务之病在官办而无市场，商办者得以自为其计，此后张之洞之布局鄂省、周学熙之启新洋灰同受此评，论西北工业之萌者必及兰州一局。", figures: ["左宗棠","赖长"], place: "甘肃兰州", state: "清", sources: ["《左宗棠全集·奏稿》","中国史学会编《洋务运动》","《（光绪）东华录》"], tags: ["机器织呢","官办工业"] }, related: ["cn--1877--m01", "cn--1889--e01"] },
  { id: "cn--1881--p01", track: "cn", year: 1881, yearApprox: false, dim: "politics", weight: 4, title: "中俄《伊犁条约》改定", summary: "有兵乃有约，还城而失其西。", detail: { background: "崇厚之约既议罪罢换，俄使坚执前说，而左宗棠以湘军进哈密，曾纪泽自伦敦移使俄国，往复半载。", process: "1881年2月中俄立《圣彼得堡条约》（通称《伊犁条约》）二十款：俄交还伊犁九城及特克斯、昭苏一带之地，而霍尔果斯河以西仍归俄有，偿兵费九百万卢布、合华银四百五十万两，准俄商至嘉峪关、乌鲁木齐、哈密、吐鲁番、焉耆、喀什噶尔通商，并许新属之民听其迁徙。", impact: "改约较崇厚原约多得特克斯、昭苏一带之地，而兵费由五百万卢布增至九百万卢布，论者以左宗棠之出关为改约有成之由，是知有兵而后可以有约；1882至1884年依约勘界，又失塔城、喀什噶尔东北一段之地，伊犁之民随俄属而去者数万，西北界址至是大定，而此约所定通商免税之条为光绪朝边税之大患。", figures: ["曾纪泽","崇厚","左宗棠"], place: "俄国圣彼得堡、新疆伊犁", state: "清", sources: ["王铁崖编《中外旧约章汇编》第一册","《清史稿·邦交志》","《清季外交史料》"], tags: ["伊犁条约","改约"] }, related: ["cn--1879--p02", "cn--1884--i01"] },
  { id: "cn--1881--e01", track: "cn", year: 1881, yearApprox: false, dim: "economy", weight: 3, title: "唐山至胥各庄铁路成", summary: "运煤之路，骡车与机车并用。", detail: { background: "开平矿务局既立（1878），煤由唐山至胥各庄之运恃驴车，雨雪则阻，成本遂昂，唐廷枢请以铁轨运之。", process: "1881年唐山至胥各庄铁路成，凡九公里余，初以骡马挽车而不用机车，以言者谓机器惊动陵寝龙脉也；翌年英商之机车至，始以蒸汽行车，矿局工程师借旧机器改装之机车亦成，俗名龙号，1886年后展筑至芦台、天津，1888年津唐路成。", impact: "唐胥一路为中国人自建铁路之始，其由骡车而机车、由运煤而载客之程，即晚清铁路之全史；至1890年代以俄法之债筑关内外之路，铁路之权与借款相因而入各国之手，论者以为三十年之迟速，其枢在官商之权而不在工技之高下。", figures: ["唐廷枢","李鸿章"], place: "直隶唐山胥各庄（今河北唐山）", state: "清", sources: ["金士宣《中国铁路发展史》","《（光绪）东华录》","中国史学会编《洋务运动》"], tags: ["唐胥铁路","自建铁路"] }, related: ["cn--1865--e01", "cn--1888--i01"] },
  { id: "cn--1882--p01", track: "cn", year: 1882, yearApprox: false, dim: "politics", weight: 3, title: "美国《排华法》之生效", summary: "以种族立禁，一国之民独受其条。", detail: { background: "1868年蒲安臣约许华人自往，1870年代美西北之工人以华工工值之廉相竞，旧金山诸地驱逐华工之乱屡起。", process: "1880年中美先订《限制华工来美之约》，1882年5月美国国会通过《排华法》，定十年之内禁华工入境而许学者、商人、游客往，其后展至无限期，并及妇女、家属，1885年怀俄明石泉城惨案、1887年丹佛之逐，华侨在美之数自十余万递减至数万。", impact: "此为美国以种族立法定禁一国侨民之始，清廷之抗议仅得其保护财产之空文；1905年抵制美货之案、1920年代废约之论皆远承此案，而华侨在美洲、南洋之业款与清末革命之资助，亦因此一法大受其阻，侨政自此为外务之一端。", figures: ["陈兰彬","黄遵宪"], place: "美国华盛顿、中国驻美使署", state: "清", sources: ["王铁崖编《中外旧约章汇编》第一册","陈翰笙编《华工出国史料汇编》","《清季外交史料》"], tags: ["排华法","华侨政策"] }, related: ["cn--1868--p01", "cn--1905--p01"] },
  { id: "cn--1882--m01", track: "cn", year: 1882, yearApprox: false, dim: "military", weight: 3, title: "朝鲜壬午兵变，清军东渡", summary: "一乱而中日之兵俱在汉城。", detail: { background: "朝鲜旧军之别技营以新军饷薄且久不给，与大臣闵妃之族、开国日本之约相激，汉城之势日危。", process: "1882年夏历六月初九朝鲜旧军起兵，杀执政数人并及日籍教官，日本使馆被毁、使者花房义质陆路走仁川登舰；清以山东抚军吴长庆督庆字三营先期东渡，执大院君李昰应解赴保定幽之，留军镇抚，袁世凯时在庆军赞画营务；日本旋续派陆兵与舰队来，立济物浦之约，赔兵费、许日本派警员驻使馆。", impact: "清于是重执朝鲜之兵权而日本得驻兵护卫之名，两国各以护其属为辞而兵皆在汉城左右；十年之间甲申之变（1884）、东学党之乱（1894）皆循此局而至，甲午战争之地形与名分已定于壬午一役，论近代中日关系者以此为转点。", figures: ["吴长庆","袁世凯","李昰应","花房义质"], place: "朝鲜汉城（今首尔）、直隶保定", state: "清", sources: ["《（光绪）东华录》","《清史稿·吴长庆传》","《朝鲜王朝实录》"], tags: ["壬午兵变","朝鲜交涉"] }, related: ["cn--1879--p01", "cn--1884--m01"] },
  { id: "cn--1883--p01", track: "cn", year: 1883, yearApprox: false, dim: "politics", weight: 3, title: "法取越南，顺化立约", summary: "藩邦之外交，移于法人之手。", detail: { background: "法国自1862、1867两约取交趾三支那六省，1873、1882两犯河内，1883年5月法提督李威利于纸桥战死，法人益兵北进，黑旗军刘永福部当其冲，越南之号令不能出南圻。", process: "1883年8月法军攻顺化，越王阮福升（协和）立第一次《顺化条约》二十七款：越南一切外交由法国代理，法国得驻钦差于顺化、驻兵于东京，中国之藩名虽存而其实已夺；朝命李鸿章、曾国荃分驻粤、滇边界，越之祀典遂绝。", impact: "越南既为法属，云南、广西之边直与法国相值；中国以藩属之兵与黑旗居间相持二年后而战，1885年《中法新约》明定中国弃越南之保，全属国之系乃解，边患由藩篱之守转为境界之争，中法界务与通商之案延至1897年之铁路权利而后定。", figures: ["刘永福","李鸿章","孤拔"], place: "越南顺化、东京河内", state: "清", sources: ["中国史学会编《中法战争》","王铁崖编《中外旧约章汇编》第一册","《清季外交史料》"], tags: ["顺化条约","越南亡"] }, related: ["cn--1879--p01", "cn--1885--p01"] },
  { id: "cn--1883--e01", track: "cn", year: 1883, yearApprox: false, dim: "economy", weight: 3, title: "上海地产钱庄之风潮", summary: "一市之银，随兵事为涨落。", detail: { background: "1880至1882年上海外商地产与华人钱庄相为投机，虚银本位、拆借无根，地产契据与股票充抵市面大半。", process: "1883年夏秋间中法战事日急，外商先自收账抛售，拆息陡长而票号观望；10月金业、茶业诸庄相继倒闭，数十家钱庄为之一空，市面存银不及往时之半（《申报》与《海关十年报告》所记多寡有异），胡雪岩在沪之生丝与银两亦因此为洋行所乘。", impact: "此为上海开埠后第一次全面金融风潮，钱庄由是改联保同人之章、外商银行得握申庄拆借之权；风潮并波及轮船招商局与各省借款，1885年议令招商局归盛宣怀整顿即以债台高垒为辞，论上海金融之脆弱与外资之居奇者以1883年为始。", figures: ["胡雪岩","李鸿章"], place: "江苏上海（今上海）", state: "清", sources: ["《申报》论市面诸文","《海关十年报告》近代史所译本","《（光绪）东华录》"], tags: ["金融风潮","钱庄"] }, related: ["cn--1877--e01", "cn--1885--e01"] },
  { id: "cn--1884--m01", track: "cn", year: 1884, yearApprox: false, dim: "military", weight: 4, title: "法舰袭马江，船政水师覆", summary: "三十刻之间，二十年之积俱尽。", detail: { background: "1883年底法取山西、北宁，1884年5月简明条约立于天津而边界之兵不退，法舰假游历之名入闽江，与船政兵轮同泊马江，而朝旨不许先行开炮。", process: "1884年8月23日法国远东舰队司令孤拔乘潮落开炮，凡三十余分钟而沉福建水师各舰十一艘（合计近万吨），官兵阵亡自七百六十余人至近千人不等，法舰受创者一二、死数人至数十人说各异；会办海疆张佩纶、船政大臣何如璋不设备而先溃，福州电线遂断，翌日法舰轰船政厂屋。", impact: "马江一役使船政二十年之积毁于一旦，而朝野之论大变：8月26日谕对法宣战，先是七月间罢恭亲王奕訢、尽斥军机诸臣（甲申易枢），朝局一归西太后，中枢不复有任事之人；海防之备专归北洋，南洋无兵可恃，甲午之局由此偏重。", figures: ["孤拔","张佩纶","何如璋","陈魁"], place: "福建闽江马江（今福州）", state: "清", sources: ["中国史学会编《中法战争》","《（光绪）东华录》","《船政奏议汇编》"], tags: ["马江之役","船政水师"] }, related: ["cn--1869--s01", "cn--1885--m01"] },
  { id: "cn--1884--c01", track: "cn", year: 1884, yearApprox: false, dim: "culture", weight: 2, title: "《点石斋画报》创刊", summary: "石印之画报，成市民之图说。", detail: { background: "《申报》馆既得石印之法，能以照相缩印、彩绘成册，遂以图像应世俗之好奇。", process: "1884年《点石斋画报》附《申报》旬刊行世，吴友如等主画事，以中法战事、西洋奇器、市井轶闻入图，一图附数百言，刻成则坊间传摹；其画法参西人之透视点石之术，凡四十余年之社会风俗多可考见。", impact: "画报之兴使不识文理之民亦得预闻时事，图画遂为开风气、动议论之具，其后《时事画报》《神州画报》继之；而吴友如所绘时人之服饰、市街、机器之形，至今为治近代社会生活史者所据，论上海之为新学与新艺之门户，画报与报馆同其功。", figures: ["吴友如"], place: "江苏上海（今上海）", state: "清", sources: ["《点石斋画报》原刊","《申报》广告","《上海新闻业之现状》"], tags: ["点石斋画报","石印技术"] }, related: ["cn--1872--c01", "cn--1897--c01"] },
  { id: "cn--1884--i01", track: "cn", year: 1884, yearApprox: false, dim: "institution", weight: 4, title: "谕新疆建省，置巡抚于迪化", summary: "军府之制改同行省，西北始与内地同其簿赋。", detail: { background: "光绪三年（1877）清军平定阿古柏之乱后，左宗棠即奏请新疆改设行省、与内地一体；时伊犁尚为俄人所据，户部以费绌、旗佐之制难骤更持之，其议延搁数年。", process: "光绪十年（1884）11月，清廷谕令新疆建立行省，设巡抚、布政使，治所在迪化，以刘锦棠为首任巡抚；府州县厅依内地章程划裁，原归参赞、办事大臣分辖的各城渐属州县，伯克征赋之权任随之而削。", impact: "西北自军府分辖转为与内地同其簿赋铨选的一省，是清末边疆改省的开端（台湾于1885年、东三省于1907年先后建省）；巡抚驻迪化之制历清末与民国而未改，今日新疆之区域由此定。", figures: ["左宗棠", "刘锦棠"], place: "新疆迪化（今乌鲁木齐）", state: "清光绪朝", sources: ["《清德宗实录》光绪朝谕令新疆建省各条", "《左宗棠全集·奏稿》请改行省诸折", "《新疆图志》建置志"], tags: ["新疆建省", "行省制", "清末边疆", "西北防务"] }, related: ["cn--1881--p01", "cn--1878--m01"] }
];
